&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;49&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;جلسه ایده‌آل (15-30 دقیقه, 1-3 فایل)، نشانه‌های هشدار&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;—&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;P6 — انواع جلسات&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;72&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;جدول تشخیص، قالب پیشنهاد، استثنا&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;(blank)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;P7 — بهبود مستمر&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;39&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;متریک‌های پیگیری، بازبینی هفته‌ای&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;(Empty)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;P8 — چک‌لیست راه‌اندازی&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;13&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پروژه جدید Bootstrap&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;—&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;P9 — مراجع&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;30&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;فایل‌های مرجع، منابع خارجی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;AGENT.adoc&lt;/code&gt;(files EAGER/LAZY)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;پیوست‌های A+B&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;42&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;واژگان, سابقة نسخه‌ها&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;—&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;قضاوت نهایی است:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;کپی‌های کامل&lt;/strong&gt;(167 خط) : P3, P4, P9 — همه چیز قبلاً داخل است`AGENT.adoc` ou &lt;code&gt;INDEX.adoc&lt;/code&gt;, معمولاً کلمه به کلمه&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;هرگز در عمل مشورت نشده&lt;/strong&gt;(215 خط) : P5, P6, P7, P8، پیوست‌ها — از حکومت متا که هیچ‌گاه در هیچ جلسه‌ای استفاده نشده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;آگاهی منحصربه‌فرد&lt;/strong&gt;(161 خط) : P1 و P2 — واژگان LAZY/EAGER، تشبیه، سیاست بارگذاری&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در 627 خط,&lt;strong&gt;382 شوم است&lt;/strong&gt;. این 382 خط در &lt;strong&gt;هر شروع جلسه&lt;/strong&gt; بارگذاری می‌شوند، توسط عامل مصرف می‌شوند و توجه او را حتی قبل از اینکه بگویم سلام، کاهش می‌دهند.&lt;/p&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-audit-result&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultTextAlignment center

title اودیت AGENT_MODUS_OPERANDI.adoc — 627 خط
left to right direction

rectangle &quot;🟡 **تکراری‌ها**\n167 خط (27%)&quot; as DUP #FFF9C4 {
  card &quot;P3 — قوانین مطلق
(34 خط)&quot; as D1
  card &quot;P4 — دوره زندگی\n(133 خط)&quot; as D2
  card &quot;P9 — منابع
(30 خط)&quot; as D3
}

rectangle &quot;🔴 **هرگز مشاوره نشده**\n215 خطوط (34%)&quot; as JAM #FFCDD2 {
  card &quot;P5 — معیارهای
(49 خط)&quot; as J1
  card &quot;P6 — تشخیص
(72 خط)&quot; as J2
  card &quot;P7 — بهبود
(39 خط)&quot; as J3
  card &quot;P8 — Bootstrap
(13 خط)&quot; as J4
  card &quot;print(&quot;پیوست‌ها \u2014 واژه‌نامه\n(42 خط)&quot;)&quot; as J5
}

rectangle &quot;🟢 **دانش یکتا**
161 خط (26%)&quot; as UNI #C8E6C9 {
  card &quot;P1 — نمای کلی
(64 خطوط)&quot; as U1
  card &quot;P2 — ساختار فایل‌ها
(97 خط)&quot; as U2
