rectangle &quot;1\nopenApiGenerate&quot; as A #FFF3E0
rectangle &quot;2\ngitProperties\n2.5.7&quot; as B #FFF3E0
rectangle &quot;3
نسخه‌ها
اصلاح‌شده&quot; as C #E3F2FD
rectangle &quot;4
تجميع OK&quot; as D #E8F5E9

A --&amp;gt; B
B --&amp;gt; C
C --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;نمودار 3 — Docker 29 / Testcontainers&lt;/div&gt;
