&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_معماری_لاینپایپ&quot;&gt;معماری لاین‌پایپ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_قطعات_داخلی&quot;&gt;قطعات داخلی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_قوانین_رnderینگ&quot;&gt;قوانین رnderینگ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحله_3_استفاده_روزانه&quot;&gt;مرحله 3: استفاده روزانه&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
