&lt;li&gt;&lt;a href=&quot;#_فیلتر_بر_اساس_جامعه&quot;&gt;فیلتر بر اساس جامعه&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_فیلتر_براساس_نوع_لبه&quot;&gt;فیلتر براساس نوع لبه&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_فیلتر_براساس_نوع_گره_و_اطمینان&quot;&gt;فیلتر براساس نوع گره و اطمینان&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_دایرکتوری_خروجی_سفارشی&quot;&gt;دایرکتوری خروجی سفارشی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرجع_کامل_ویژگیها&quot;&gt;مرجع کامل ویژگی‌ها&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_پایپلاین_کامل_در_گردش_کار_گرادل&quot;&gt;پایپلاین کامل در گردش کار گرادل&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_نوع_گردش_کار&quot;&gt;نوع گردش کار&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ادغام_در_چرخه_توسعه&quot;&gt;ادغام در چرخه توسعه&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_بهروزرسانی_افزایشی&quot;&gt;به‌روزرسانی افزایشی&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_دگفودینگ_پلاگین_خود_را_مستند_میکند&quot;&gt;دگفودینگ: پلاگین خود را مستند می‌کند&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_چرا_این_تعیینپذیر_است_و_چرا_مهم_است&quot;&gt;چرا این تعیین‌پذیر است (و چرا مهم است)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_دیاگرامهای_خود_pipeline&quot;&gt;دیاگرام‌های خود pipeline&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_یکپارچهسازی_در_مدیریت_پروژه&quot;&gt;یکپارچه‌سازی در مدیریت پروژه&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_پیکربندی_چکلیست_در_۵_دقیقه&quot;&gt;پیکربندی: چک‌لیست در ۵ دقیقه&lt;/a&gt;&lt;/li&gt;
