&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دروس_آموختگی&quot;&gt;دروس آموختگی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

rectangle &quot;**نصب محلی**\n در خانه&quot; as install #LightGreen {
    card &quot;sudo نیست
 برای ویرایش CSS/config&quot; as i1
    card &quot;opencode+LLM می‌تواند\n همه چیز را تغییر دهد&quot; as i2
    card &quot;Rollback = بازگردانی
 بکاپ با timestamp&quot; as i3
}

rectangle &quot;**CSS سفارشی**
بزرگنمایی vs اندازه فونت&quot; as css #LightYellow {
    card &quot;بزرگنمایی &amp;gt; اندازه-فونت\n برای لیست کامپوننت‌ها&quot; as c1
    card &quot;Layout JS override
 height/line-height&quot; as c2
    card &quot;CSS سفارشی افزونه
نیاز به فعال‌سازی
دستی (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;اتوماسیون
اسکریپت به‌روزرسانی&quot; as auto #LightCoral {
    card &quot;بازپatch CSS پس از
هر به‌روزرسانی&quot; as a1
    card &quot;حذف جمع‌بررسی‌ها\n product.json&quot; as a2
    card &quot;بکاپ با timestamp
قبل از جایگزینی&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

note top of auto
  Sans script, chaque MAJ
  efface les patches CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نصب_در_home_همه_چیز_را_آزاد_میکند&quot;&gt;نصب در home همه چیز را آزاد می‌کند&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یک نصب محلی در`~/apps`کنترل کامل بر VS Code را می‌دهد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;نه`sudo`برای تغییر CSS یا تنظیمات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آjánک opencode+LLM می‌تواند در فایل‌های تنظیمات و منابع IDE بنویسد.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بازگرداندن trivial: بازگرداندن بکاپ دارای تاریخ و زمان&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zoom_font_size_برای_اجزای_لیست&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; برای اجزای لیست&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code از طریق JavaScript ارتفاع خطوط را کنترل می‌کند. ویرایش`font-size`عدم توانایی در دسترس کردن به ارتفاع اختصاص‌یافته توسط موتور چیدمان، منجر به débord شدن متن می‌شود. ویژگی`zoom`بر روی والد conteneur، بزرگ کردن همه به صورت نسبتی این مشکل را دور می‌زند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افزونه_custom_css_نیاز_به_فعالسازی_صریح_دارد&quot;&gt;افزونه Custom CSS نیاز به فعال‌سازی صریح دارد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این یک پارامتر &#39;set and forget&#39; نیست. هر تغییری در فایل CSS سفارشی نیاز به اجرای مجدد «Enable Custom CSS and JS» از تلوی فرمان دارد (&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یک_اسکریپت_بهروزرسانی_ضروری_است&quot;&gt;یک اسکریپت به‌روزرسانی ضروری است&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بدون اسکریپت، هر به‌روزرسانی از VS Code، پچ‌های CSS workbench را پاک می‌کند. اسکریپت`vscode-update.sh`اتوماتیک می‌کند دانلود، جایگزینی، بازپچ و پاکسازی چک‌سمرها.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مراجع_سریع&quot;&gt;مراجع سریع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;دانلود VS Code : &lt;a href=&quot;https://code.visualstudio.com/Download&quot; class=&quot;bare&quot;&gt;https://code.visualstudio.com/Download&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بارگیر CSS و JS سفارشی افزونه :`be5invis.vscode-custom-css`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مسئله VS Code که یک تنظیم بومی برای فونت کاویژه می‌خواهد:https://github.com/microsoft/vscode/issues/149[github.com/microsoft/vscode#149]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

