&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_بینش_معماری&quot;&gt;بینش معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_راهنما&quot;&gt;اصول راهنما&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری برپای اصل &lt;strong&gt;جدا‌سازی نگرانی‌ها&lt;/strong&gt; است :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوا&lt;/strong&gt; : فایل‌های AsciiDoc ساختار یافته با متاداده‌های غنی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;معرفی&lt;/strong&gt; : قالب‌های Thymeleaf قابلِ استفاده دوباره&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;داده‌ها&lt;/strong&gt; : مدل استخراج خودکار توسط JBake از ویژگی‌های AsciiDoc&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;استایل&lt;/strong&gt;: Bootstrap 5 برای اتساق بصری&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_انتخاب_استراتژیک_asciidoc_برای_پورتفولیو&quot;&gt;انتخاب استراتژیک : AsciiDoc برای پورتفولیو&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;caption class=&quot;title&quot;&gt;Table 1. چرا AsciiDoc ?&lt;/caption&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;معیار&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مزیت&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;همسویی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مثل قالب مقالات وبلاگ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;متاداده&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ویژگی‌های ساختاری و قابل توسعه (&lt;code&gt;project-*&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;قابلیت نگهداری&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ویرایش ساده متن، گیت قابل نسخ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;انعطاف‌پذیری&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ممکن است شامل محتوای غنی (جداول، کد، تصاویر) باشد.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;قالب‌سازی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake به‌صورت خودکار ویژگی‌ها را برای Thymeleaf استخراج می‌کند&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مدل_داده&quot;&gt;مدل داده&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هر پروژه پورتفولیو یک سند AsciiDoc است که :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;میتادیتای سربرگ&lt;/strong&gt; : اطلاعات ساختار‌دار (مشتری، مدت، فناوری‌ها، و غیره)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بدن سند&lt;/strong&gt; : توضیح داستانی، چالش‌ها، راه‌حل‌ها، نتایج&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ویژگی‌های سفارشی&lt;/strong&gt; : پیشوند شده`project-*`برای استخراج خودکار&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;پروژه&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  --
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  --
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_موردهای_استفاده_دقیق&quot;&gt;موردهای استفاده دقیق&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc1_افزودن_یک_آیتم_به_پورتفو&quot;&gt;UC1 : افزودن یک آیتم به پورتفو&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_فلوز_نرمال&quot;&gt;فلوز نرمال&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;ویرایشگر
متن&quot; as editor
participant &quot;File\nAsciiDoc&quot; as file
participant &quot;JBake
موتور&quot; as jbake
participant &quot;سایت\nثابت&quot; as site

dev -&amp;gt; editor : Créer nouveau fichier
activate editor
editor -&amp;gt; file : portfolio/nouveau-projet.adoc
activate file

dev -&amp;gt; editor : Rédiger en-tête avec métadonnées\n(titre, type=project, status=published,\nattributs project-*)
dev -&amp;gt; editor : Rédiger contenu narratif\n(contexte, défis, solutions)
dev -&amp;gt; editor : Ajouter images dans assets/img/portfolio/

editor -&amp;gt; file : Sauvegarder
deactivate editor

dev -&amp;gt; jbake : Lancer build (jbake -b)
activate jbake
jbake -&amp;gt; file : Lire et parser
jbake -&amp;gt; jbake : Extraire métadonnées
jbake -&amp;gt; jbake : Convertir AsciiDoc → HTML
jbake -&amp;gt; jbake : Appliquer template project.html
jbake -&amp;gt; jbake : Ajouter à la liste portfolio.html
jbake -&amp;gt; site : Générer pages statiques
deactivate jbake

dev -&amp;gt; site : Vérifier résultat
activate site
site --&amp;gt; dev : Afficher projet
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_قالب_فایلی_که_باید_ایجاد_شود&quot;&gt;قالب فایلی که باید ایجاد شود&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;توسعه‌دهنده می‌سازد`content/portfolio/nom-projet.adoc`با یک ساختار استاندارد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;سربرگ با تمام ویژگی‌های مورد نیاز&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بخش‌های استانداردی (زمینه, چالش‌ها, راه‌حل‌ها, نتایج)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نامگذاری همسو تصاویر&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_نقاط_اعتبارسنجی&quot;&gt;نقاط اعتبارسنجی&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ویژگی‌های الزامی وجود دارند`jbake-type`, &lt;code&gt;jbake-status&lt;/code&gt;, &lt;code&gt;project-thumbnail&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تصاویر ارجاع‌شده در`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ساخت JBake با موفقیت و بدون خطا انجام می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پروژه در صفحه پورتفولیو نمایش داده می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;صفحه‌ی فردی پروژه به درستی نمایش داده می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc2_حذف_یک_عنصر_از_پورتفو&quot;&gt;UC2 : حذف یک عنصر از پورتفو&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_فلکس_نمینی&quot;&gt;فلکس نمینی&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;سیستم\nفایل‌ها&quot; as fs
participant &quot;JBake
موتور&quot; as jbake
participant &quot;سایت
استاتیک&quot; as site
database &quot;کش\nJBake&quot; as cache

dev -&amp;gt; fs : Supprimer portfolio/projet-ancien.adoc
activate fs
fs --&amp;gt; dev : Fichier supprimé
deactivate fs

dev -&amp;gt; fs : (Optionnel) Supprimer images associées\nassets/img/portfolio/projet-ancien-*
activate fs
fs --&amp;gt; dev : Images supprimées
deactivate fs

dev -&amp;gt; cache : Nettoyer cache JBake
activate cache
cache --&amp;gt; dev : Cache vidé
deactivate cache

dev -&amp;gt; jbake : Rebuild complet (jbake -b)
activate jbake
jbake -&amp;gt; jbake : Scanner content/portfolio/
jbake -&amp;gt; jbake : Projet absent → non généré
jbake -&amp;gt; jbake : Régénérer portfolio.html\n(sans le projet supprimé)
jbake -&amp;gt; site : Déployer nouveau build
deactivate jbake

dev -&amp;gt; site : Vérifier
activate site
site --&amp;gt; dev : Projet absent de la liste
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_استراتژی_جایگزین_بایگانی&quot;&gt;استراتژی جایگزین : بایگانی&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به جای حذف دائم، امکان ایجاد یک پوشه وجود دارد.&lt;code&gt;content/portfolio/archive/&lt;/code&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;به جای حذف آن، فایل را جابجا کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;به‌راحتی امکان بازگردانی را فراهم می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تاریخچه Git را واضح‌تر نگه دار&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_پاکسازی_منابع&quot;&gt;پاک‌سازی منابع&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بررسی تصاویر یتیم در`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تصاویر که توسط پروژه‌های دیگر ارجاع داده نشده‌اند را حذف کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پاک کردن کش JBake برای جلوگیری از مراجع فانتوم&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc3_تنظیم_به_پیشنویس_پیشنویس&quot;&gt;UC3 : تنظیم به پیش‌نویس (پیش‌نویس)&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_فلوكس_نومینال&quot;&gt;فلوكس نومینال&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;فایل
AsciiDoc&quot; as file
participant &quot;JBake
موتور&quot; as jbake
participant &quot;سایت
استاتیک&quot; as site

dev -&amp;gt; file : Ouvrir portfolio/projet.adoc
activate file

dev -&amp;gt; file : Modifier attribut\n:jbake-status: published\n↓\n:jbake-status: draft

file --&amp;gt; dev : Sauvegardé
deactivate file

dev -&amp;gt; jbake : Rebuild (jbake -b)
activate jbake
jbake -&amp;gt; file : Parser le fichier
jbake -&amp;gt; jbake : Détecter status=draft
jbake -&amp;gt; jbake : Exclure de published_projects
jbake -&amp;gt; jbake : Ne pas créer page publique
note right
  Le projet existe toujours
  mais n&#39;est pas publié
end note
jbake -&amp;gt; site : Générer site (sans ce projet)
deactivate jbake

dev -&amp;gt; site : Vérifier portfolio
activate site
site --&amp;gt; dev : Projet absent de la liste publique
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_وضعیتهای_ممکن&quot;&gt;وضعیت‌های ممکن&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

[*] --&amp;gt; Draft : Création initiale
Draft --&amp;gt; Published : Validation et publication
Published --&amp;gt; Draft : Retrait temporaire
Draft --&amp;gt; Archived : Projet abandonné
Published --&amp;gt; Archived : Projet obsolète
Archived --&amp;gt; [*] : Suppression définitive
Published --&amp;gt; Published : Mises à jour

note right of Draft
  :jbake-status: draft
  Non visible publiquement
  Utile pour projets en cours
end note

note right of Published
  :jbake-status: published
  Visible sur le portfolio
  Indexé par JBake
end note

note right of Archived
  Déplacé dans archive/
  ou jbake-status: archived
  Non publié mais conservé
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_موردهای_استفادهٔ_معمولی&quot;&gt;موردهای استفادهٔ معمولی&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروژه در حال تدوین&lt;/strong&gt; : ایجاد به‌عنوان پیش‌نویس، منتشر کردن وقتی آماده باشد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروژه موقتاً محرمانه&lt;/strong&gt; : به پیش‌نویس 전환 تا زمان توافق با مشتری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;به‌روزرسانی بزرگ&lt;/strong&gt; : تغییر به پیش‌نویس، ویرایش، انتشار مجدد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A/B testing&lt;/strong&gt; : به‌عنوان پیش‌نویس کپی کردن، تست کردن و انتشار بهترین نسخه&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماری_تمپلیت&quot;&gt;معماری تمپلیت&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استراتژی_الگوهای_قابل_استفاده_مجدد&quot;&gt;استراتژی الگوهای قابل استفاده مجدد&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;قالب‌های Thymeleaf&quot; {
  component [index.html] as index
  component [portfolio.html] as portfolio
  component [project.html] as project

  package &quot;قسمت‌های جزئی&quot; {
    component [header.html] as header
    component [footer.html] as footer
    component [project-card.html] as card
    component [tech-badge.html] as badge
    component [gallery.html] as gallery
  }
}

package &quot;داده‌های JBake&quot; {
  database &quot;پروژه‌های منتشر شده&quot; as data
  database &quot;محتوا (پروژه)&quot; as content
}

index --&amp;gt; header
index --&amp;gt; footer

portfolio --&amp;gt; header
portfolio --&amp;gt; footer
portfolio --&amp;gt; card
data --&amp;gt; portfolio : itération

project --&amp;gt; header
project --&amp;gt; footer
project --&amp;gt; badge
project --&amp;gt; gallery
content --&amp;gt; project : projet individuel

note right of card
  Fragment réutilisable
  pour afficher une carte
  de projet avec :
  - thumbnail
  - titre
  - tags
  - highlights
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الگوی_استخراج_دادهها&quot;&gt;الگوی استخراج داده‌ها&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake به صورت خودکار ویژگی‌های AsciiDoc را به ویژگی‌های قابل دسترسی در Thymeleaf تبدیل می‌کند:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;سند AsciiDoc&quot; {
  (&quot;:project-client: Acme Corp&quot;) as attr1
  (&quot;:project-duration: 6 ماه&quot;) as attr2
  (&quot;:project-tags: java, react&quot;) as attr3
}

rectangle &quot;مدل JBake&quot; {
  (content[&#39;project-client&#39;]) as prop1
  (content[&#39;project-duration&#39;]) as prop2
  (content.tags) as prop3
}

rectangle &quot;قالب Thymeleaf&quot; {
  (th:text=&quot;${project[&#39;project-client&#39;]}&quot;) as tmpl1
  (th:text=&quot;${project[&#39;project-duration&#39;]}&quot;) as tmpl2
  (th:each=&quot;برچسب : ${project.tags}&quot;) as tmpl3
}

attr1 --&amp;gt; prop1 : parsing
attr2 --&amp;gt; prop2 : parsing
attr3 --&amp;gt; prop3 : parsing

prop1 --&amp;gt; tmpl1 : binding
prop2 --&amp;gt; tmpl2 : binding
prop3 --&amp;gt; tmpl3 : binding
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قوانین_نامگذاری&quot;&gt;قوانین نامگذاری&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ویژگی‌های پروژه&lt;/strong&gt; : پیشوند`project-*` (ex: &lt;code&gt;project-client&lt;/code&gt;, &lt;code&gt;project-tech-stack&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فایل‌ها&lt;/strong&gt; : kebab-case (مثال:`ecommerce-platform.adoc`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Images&lt;/strong&gt; : پیشوند نام پروژه (مثال:`ecommerce-platform-thumb.jpg`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Templates&lt;/strong&gt; : نام کارکردی (مثال:`project-card.html`, &lt;code&gt;tech-badge.html&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فرآیند_کار_انتشار&quot;&gt;فرآیند کار انتشار&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_خط_أنابيب_توسعه&quot;&gt;خط أنابيب توسعه&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;پروژه&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  __
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  __
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_محیطها&quot;&gt;محیط‌ها&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;محیط&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;استفاده&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;وضعیت پذیرفته‌شده&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;محلی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;توسعه و پیش‌نمایش&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پیش‌نویس، منتشر شده&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;آماده‌سازی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;اعتبار پیش تولید&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;منتشر شده فقط&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;تولید&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;سایت عمومی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;فقط منتشر شده&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_قابلیت_گسترش&quot;&gt;قابلیت گسترش&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افزودن_ویژگیهای_جدید&quot;&gt;افزودن ویژگی‌های جدید&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای غنی‌سازی مدل داده، کافی است ویژگی‌های جدیدی با پیشوند اضافه کنید.&lt;code&gt;project-*&lt;/code&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-awards&lt;/code&gt;: جوایز و تقدیرات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-testimonial&lt;/code&gt;: نقل‌قول مشتری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-team-size&lt;/code&gt;: اندازه تیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`project-budget-range`دامنه بودجه&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این ویژگی‌ها به طور خودکار در قالب‌ها در دسترس می‌شوند بدون نیاز به تغییر در موتور JBake&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دستهبندی_پیشرفته&quot;&gt;دسته‌بندی پیشرفته&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

object Projet {
  project-category = &quot;وب&quot;
  project-subcategory = &quot;تجاره الکترونیک&quot;
  project-industry = &quot;فروش جزئی&quot;
  project-complexity = &quot;بالا&quot;
}

object Taxonomie {
  categories : [web, mobile, data, devops]
  subcategories : Map&amp;lt;category, List&amp;gt;
  industries : [retail, finance, healthcare, ...]
  complexities : [low, medium, high]
}

Projet --&amp;gt; Taxonomie : classifié selon

note right of Taxonomie
  Permet filtrage multi-critères
  dans le template portfolio.html
  via JavaScript ou côté serveur
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_روشهای_خوب&quot;&gt;روش‌های خوب&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سازماندهی_فایلها&quot;&gt;سازماندهی فایل‌ها&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;یک فایل = یک پروژه&lt;/strong&gt; : از ترکیب چندین پروژه خودداری کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تصاویر در پوشه مخصص&lt;/strong&gt;&lt;code&gt;assets/img/portfolio/nom-projet/&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;نامگذاری سازگار&lt;/strong&gt; : تسهیل جستجو و نگهداری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Versioning Git&lt;/strong&gt; : پیگیری کامل تغییرات&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مدیریت_محتوا&quot;&gt;مدیریت محتوا&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;وضعیت پیش‌نویس پیش‌فرض&lt;/strong&gt; : فقط وقتی آماده باشد منتشر شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بررسی قبل از انتشار&lt;/strong&gt; : تأیید کیفیت و حریم خصوصی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;متادیتاهای کامل&lt;/strong&gt; : تمام فیلدهای مرتبط را پر کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوای روایت غنی&lt;/strong&gt; : به متاداده‌ها محدود نشوید&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عملکرد&quot;&gt;عملکرد&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بهینه‌سازی تصاویر&lt;/strong&gt; : فشرده‌سازی قبل از commit&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;صفحه‌بندی در صورت نیاز&lt;/strong&gt; : اگر &amp;gt;20 پروژه‌ها&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Lazy loading&lt;/strong&gt; : تصاویر گالری‌ها به‌صورت تحت‌طلب بارگذاری می‌شوند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;کش مرورگر&lt;/strong&gt; : هدرهای مناسب برای دارایی‌ها&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه&quot;&gt;نتیجه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این معماری امکان می‌دهد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;سادگی استفاده&lt;/strong&gt; : افزودن یک پروژه = ایجاد یک فایل متنی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لچ‌پذیری&lt;/strong&gt; : قابل توسعه با ویژگی‌های جدید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;قابلیت نگهداری&lt;/strong&gt; : جدایی محتوا/نمایش&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پیگیری&lt;/strong&gt; : نسخهٔ کامل Git&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اتوماسیون&lt;/strong&gt; : ساخت و استقرار مستمر ممکن است&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;انتخاب AsciiDoc همگونی با بقیه سایت را تضمین می‌کند و در عین حال ثروت ماداده‌های لازم برای یک پورتفوی حرفه‌ای را ارائه می‌دهد.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;زمان خواندن : 12 minutes&lt;/div&gt;
&lt;p&gt;به‌جای این‌که بین سادگی Supabase و قدرت Spring Boot انتخاب کنید، چرا آن‌ها را ترکیب نکنید؟ معماری هیبریدی را که بهترین ویژگی‌های هر فناوری را به کار می‌گیرد، کشف کنید.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;تیک&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دیلما_دروغ_معماری_مدرن&quot;&gt;دیلما دروغ معماری مدرن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هنگامی که یک برنامه مدرن با یک frontend استاتیک ساخته می‌شود، معمولاً به یک انتخاب باینری (دودویی) مواجه می‌شویم:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;همه چیز را بر روی یک راه‌حل Backend-as-a-Service بگذار&lt;/strong&gt;(Supabase, Firebase) - ساده اما محدود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;یک بک‌اند کامل بسازید&lt;/strong&gt;(Spring Boot, Node.js) - قوی اما پیچیده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این گزینش یک معضل کاذب است. معماری هیبریدی یک راه سوم پیشنهاد می‌دهد: &lt;strong&gt;استفاده از هر فناوری جایی که بهتر است&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دیده_معماری&quot;&gt;دیده معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معماری_سنتی_تکبلوک&quot;&gt;معماری سنتی : تک‌بلوک&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;معماری سنتی&quot; {
  actor Utilisateur as user
  component &quot;فرانت‌اند&quot; as frontend #LightBlue
  component &quot;بک‌اند مونولیتیک&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;پایگاه داده&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در این رویکرد، حتی عملیات ساده‌ترین‌ها (خواندن یک مقاله، ایجاد یک نظر) باید از طریق بک‌اند شما عبور کنند. از روز اول هزینهٔ پیچیدگی را می‌پردازید.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معمار_baas_herald_نماینده&quot;&gt;معمار BaaS : herald نماینده&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;معماری BaaS خالص&quot; {
  actor Utilisateur as user
  component &quot;فرونت‌اند&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به عکس، واگذاری کامل به یک BaaS در ابتدا جذاب به‌نظر می‌رسد اما هرچون که منطق کسب‌وکار پیچیده می‌شود، به سرعت محدودیت‌هایش آشکار می‌شود.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معماری_هیبریدی_جداسازی_مسئولیتها&quot;&gt;معماری هیبریدی : جداسازی مسئولیت‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;لایهٔ فرانت‌اند&quot; {
  component &quot;سایت استاتیک JBake&quot; as frontend #SkyBlue
}

package &quot;لایه ساده (Supabase)&quot; #LightGreen {
  component &quot;احراز هویت&quot; as auth
  component &quot;CRUD أساسي&quot; as crud
  component &quot;ذخیره فایل‌ها&quot; as storage
  component &quot;زمان واقعی&quot; as realtime
}

package &quot;لایه کاری (Spring Boot)&quot; #Coral {
  component &quot;منطق پیچیده&quot; as logic
  component &quot;آراسترایی&quot; as orchestration
  component &quot;وظایف برنامه‌ریزی شده&quot; as jobs
  component &quot;یکپارچه‌سازی‌ها&quot; as integrations
}

database &quot;PostgreSQL مشترک&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبرید مسئولیت‌ها را به صورت واضح بر اساس پیچیدگی و طبیعت عملیات‌های آن جدا می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اصول_طراحی&quot;&gt;اصول طراحی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصل_1_شروع_به_سادهگی_توسعه_هوشمندانه&quot;&gt;اصل 1: شروع به سادهگی، توسعه هوشمندانه&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**فاز 1: MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;فاز 2 : رشد&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (اختیاری)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;مرحله ۳ : مقیاس&quot; #LightCoral {
  component &quot;معماری کامل&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اگر به Spring Boot نیاز ندارید، آن را ساخت نکنید.&lt;/strong&gt;با Supabase شروع کنید، Spring Boot را وقتی پیچیدگی آن را justified می‌دانید، اضافه کنید.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_۲_جداسازی_بر_اساس_طبیعت_عمل&quot;&gt;مبدأ ۲: جداسازی بر اساس طبیعت عمل&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_۳_یک_منبع_حقیقت&quot;&gt;مبدأ ۳: یک منبع حقیقت&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;اسکیما: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;طرح: عمومی (به اشتراک)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Schema: business (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به اشتراک‌گذاری یک نمونه PostgreSQL، Supabase و Spring Boot بر روی داده‌های یکسان کار می‌کنند بدون نیاز به همگام‌سازی پیچیده.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ارگسترای_جریانها&quot;&gt;ارگسترای جریان‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_1_احراز_هویت_مرکزی&quot;&gt;Flux 1 : احراز هویت مرکزی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;کاربر&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;احراز هویت Supabase&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;وارد شوید&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;نکته کلید&lt;/strong&gt;: یک فرآیند احراز هویت، یک JWT، در هر جا قابل استفاده است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_2_تنظیم_یک_فرآیند_کسب_و_کار_پیچیده&quot;&gt;Flux 2: تنظیم یک فرآیند کسب و کار پیچیده&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;مشتری&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;اسپرینگ بوت&quot; as spring
participant &quot;Supabase DB&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;سرویس انبار&quot; as inventory
participant &quot;سرویس ایمیل&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;چه چیزی Spring Boot می‌آورد&lt;/strong&gt;ارکیسترهی قابل اعتماد از فرآیندهای پیچیده شامل چندین سیستم با تضمین تراکنشنی&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلو_3_کارهای_برنامهریزیشده_و_همگامسازیها&quot;&gt;فلو 3: کارهای برنامه‌ریزی‌شده و همگام‌سازی‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Scheduler\n(Spring Boot)&quot; as scheduler
participant &quot;سرویس گزارش&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;API خارجی&quot; as api
participant &quot;سرویس ایمیل&quot; as email
participant &quot;ذخیره‌سازی Supabase&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;چه چیزی Spring Boot می‌آورد&lt;/strong&gt;وظائف برنامه‌ریزی‌شده قابل اعتماد با مدیریت وضعیت، تلاش خودکار و اجرای مضمون&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ماتریس_تصمیمگیری&quot;&gt;ماتریس تصمیم‌گیری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_supabase_را_چه_زمانی_استفاده_کنیم&quot;&gt;Supabase را چه زمانی استفاده کنیم؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_spring_boot_را_چه_زمانی_استفاده_کنیم&quot;&gt;Spring Boot را چه زمانی استفاده کنیم؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نمونههای_معماری_بر_اساس_نوع_پروژه&quot;&gt;نمونه‌های معماری بر اساس نوع پروژه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_وبلاگ_پرتفلئو&quot;&gt;وبلاگ / پرتفلئو&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;بلاگ شخصی - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (مجانا)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (اختیاری)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (اختیاری)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حکم&lt;/strong&gt;: 100% Supabase به‌طور کافی است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_برنامه_saas&quot;&gt;برنامه SaaS&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;برنامه SaaS - معماری هیبرید&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;خدمات خارجی&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL اشتراکی&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حکم&lt;/strong&gt;: لازم است معماری هیبرید باشد. Supabase برای بخش اصلی، Spring Boot برای بخش حیاتی (پرداخت‌ها، صورتحساب).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تجارت_الکترونیک&quot;&gt;تجارت الکترونیک&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;تجارت الکترونیک - 70% Spring Boot&quot; {
  component &quot;فروشگاه (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (فعالیت اصلی)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;یک‌پارچه‌سازی‌ها&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (فعالیت اصلی)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حکم&lt;/strong&gt;: Spring Boot ضروری است. Supabase فقط برای احراز هویت و فهرست.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استراتژی_مهاجرت_تدریجی&quot;&gt;استراتژی مهاجرت تدریجی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_هزینها_و_ملاحظات_عملیاتی&quot;&gt;هزین‌ها و ملاحظات عملیاتی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ساختار_هزینهها&quot;&gt;ساختار هزینه‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;هزینۇ ماهانه تخمین‌زده&quot; {

  rectangle &quot;مرحله MVP
(0-1000 کاربر)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;مرحله رشد
(1k-10k کاربر)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;مرحله مقیاس‌پذیری\n(10k-100k کاربران)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;مرحله مقیاس‌پذیری\n(10k-100k کاربران)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مسئولیتهای_عملیاتی&quot;&gt;مسئولیت‌های عملیاتی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;کسی چه چیزی را مدیریت می‌کند؟&quot; {

  rectangle &quot;مدیریت شده توسط Supabase (بدون تلاش)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;مدیریت‌شده توسط گیت‌هاب (بدون تلاش)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;مدیریت (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;مدیریت (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه_تعادل_کامل&quot;&gt;نتیجه : تعادل کامل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبریدی Supabase + Spring Boot نه یک تنازل است، این یک&lt;strong&gt;همکاری&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_که_باید_به_خاطر_سپرد&quot;&gt;اصول که باید به خاطر سپرد&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_كي_انتخاب_این架构&quot;&gt;كي انتخاب این架构؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;این معماری ایده‌آل است اگر :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;می‌خواهید به‌سرعت شروع کنید (MVP به‌روز، نه ماه)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما پیش‌بینی می‌کنید رشد پیچیدگی کاری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما می‌خواهید هزینه‌های اولیه را به حداقل برسانید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما PostgreSQL را دوست دارید و می‌خواهید منبع یکتا از حقیقت داشته باشید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما Kotlin و Coroutines را برای کد کسب‌وکار دوست دارید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما می‌خواهید vendor lock-in کامل را جلوگیری کنید.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ این معماری برای این مناسب نیست اگر:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;پروژه شما ساده است و همچنان ساده خواهد بود (وبلاگ شخصی → 100% Supabase کافی است)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما یک پشته بک‌اندی (backend) مستقر دارید که آن را تسلط دارید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;یک منولیت سنتی را ترجیح می‌دهید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما نیاز دارید به .NET، Python یا یک زبان backend دیگر&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دیدان_کلی_نهایی&quot;&gt;دیدان کلی نهایی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;معماری هیبرید کامل&quot; {

  actor &quot;کاربران&quot; as users

  rectangle &quot;فرانت‌اند (استاتیک)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend ساده (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;بک‌اند تجاری (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
منبع یکتای حقیقت&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بهترین_دو_جهان&quot;&gt;بهترین دو جهان&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این معماری شما را می‌دهد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 سرعت Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;شروع به ساعت، نه به هفته&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;احراز هویت OAuth2 در چند کلیک&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIهای REST به‌صورت خودکار تولید شده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پیکربندی صفر سرور&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 قدرت Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin و Coroutines برای کد غیرهمگام زیبا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;همآهنگ‌سازی فرآیندهای تجاری پیچیده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کارهای زمان‌بندی‌شده قابل اعتماد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تراکنش‌های ACID تضمین‌شده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اکوسیستم Spring کامل&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 اقتصاد پیشرو&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ برای شروع و تأیید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;هزین‌هایی که رشد را دنبال می‌کنند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بدون مهندسی پیش‌زمان بیش از حد&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 انعطاف‌پذیری معماری&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;مهاجری تدریجی بدون بازسازی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;افزودن Spring Boot فقط در صورت لزوم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;هیچ قفل‌به‌فروشنده‌ی کامل نیست&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;معماری تطبیقی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_برای_پیشرفت_بیشتر&quot;&gt;برای پیشرفت بیشتر&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_منابع_فنی&quot;&gt;منابع فنی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مستندات Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;راهنمای احراز هویت&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Row Level Security&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;APIهای خودکار&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مستندات Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot با Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutine‌ها و Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;سرور منبع JWT&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مقالات تکمیلی :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;امن‌سازی API‌ها با JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بهینه‌سازی عملکرد PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;الگوهای مهاجرت تدریجی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مدیریت خطاها در معماری توزیع‌شده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_موردهای_استفاده_واقعی&quot;&gt;موردهای استفاده واقعی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این معماری هیبرید با موفقیت در :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: احراز هویت Supabase، صورتحساب Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بازارها&lt;/strong&gt;: کتگ Supabase, تراکنش‌های Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پلتفرم‌های محتوا&lt;/strong&gt;: مقالات Supabase, analytics Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ابزارهای داخلی&lt;/strong&gt;CRUD Supabase، گردش کارهای Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فهرست_راهاندازی&quot;&gt;فهرست راه‌اندازی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحله 1 - مبنا (هفته 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; ایجاد حساب Supabase - [ ] پروژه PostgreSQL را پیکربندی کنید - [ ] فعال‌سازی احراز هویت (گوگل، گیت‌هاب) - [ ] تعریف طرح اولیه - [ ] تنظیم Row Level Security - [ ] APIها را از JBake تست کنید&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فاز 2 - MVP (هفته 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; پیاده‌سازی صفحات اصلی - [ ] ادغام احراز هویت OAuth2 - [ ] ایجاد فرم‌های CRUD - [ ] تنظیم Storage برای فایل‌ها - [ ] قرار دادن روی GitHub Pages - [ ] آزمایش در شرایط واقعی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحله 3 - تکامل (بر اساس نیازها)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; شناسایی نیازهای منطقی پیچیده - [ ] ایجاد پروژه Spring Boot در صورت نیاز - [ ] تنظیم اعتبار JWT Supabase - [ ] متصل کردن به PostgreSQL Supabase - [ ] مهاجرت ویژگی‌های پیچیده - [ ] پیاده‌سازی کارهای زمان‌بندی شده - [ ] استقرار Spring Boot (Cloud Run، و غیره)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الگوهای_ضد_که_باید_اجتناب_کرد&quot;&gt;الگوهای ضد که باید اجتناب کرد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ نکنید :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;داده‌ها بین Supabase و Spring Boot کپی کردن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایجاد دو پایگاه داده PostgreSQL جداگانه&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خودتان احراز هویت را کد بنویسید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از Spring Boot برای CRUD ساده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;از ابتدایی بیش از حد معماری کردن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase Row Level Security را نادیده بگیرید&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بهتر است انجام دهید :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;یک پایگاه داده PostgreSQL را به اشتراک بگذار&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase را اجازه دهید که احراز هویت را مدیریت کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از Spring Boot فقط برای پیچیدگی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شروع به سادگی، پیشرفت به تدریج&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از نقاط قوت هر فناوری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایمن‌سازی با RLS در سطح پایگاه donnée&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_منظورهای_تکامل&quot;&gt;منظورهای تکامل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افزودن_توانمندیهای_جدید&quot;&gt;افزودن توانمندی‌های جدید&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;معماری فعلی&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;تحولات ممکن&quot; #LightYellow {

  package &quot;عملکرد&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;نظارت&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;ویژگی‌ها&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مقیاس_افقی&quot;&gt;مقیاس افقی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هنگامی که برنامه شما رشد می‌کند، معماری هیبریدی به‌طور خودکار مقیاس‌پذیر می‌شود:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;به‌صورت خودکار تا میلیون‌های opérations مقیاس‌پذیر می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas برای عملکرد خواندن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بازیابی نقطه‌ای برای امنیت&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اسپرینگ بوت :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;چندین نمونه پشت load balancer&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;طراحی بی‌حالت مقیاس‌گیری افقی را تسهیل می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes برای orchestretion در صورت نیاز&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;پارتیشن‌بندی برای جداول حجیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Connection pooling (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شاردینگ واقعاً ضروری (نادر)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_گواهینماریهای_معماری&quot;&gt;گواهینماری‌های معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استارتاپ_saas_۵۰هزار_کاربر&quot;&gt;استارتاپ SaaS (۵۰هزار کاربر)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ ما با 100% Supabase شروع کردیم. در 5k کاربر، Spring Boot را صرفاً برای پرداخت Stripe و گزارش‌های ماهانه اضافه کردیم. یک سال بعد، 80% از عملیات‌های ما همچنان از طریق Supabase انجام می‌شود. Spring Boot فقط بخش حیاتی را مدیریت می‌کند. این جداسازی به ما اجازه داد تا مقیاس کنیم بدون نیاز به بازنویسی. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پلتفرم_e_learning_10k_کاربر&quot;&gt;پلتفرم E-learning (10k کاربر)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ احراز هویت OAuth2 Supabase ما را سه هفته زمان توسعه صرفه‌جویی کرد. API‌های خود تولید شده فهرست دوره‌های ما را مدیریت می‌کنند. Spring Boot فقط برای گواهینامه‌های PDF و ایمیل‌های پیشرفت به کار می‌رود. معماری ساده، قابل‌ حفظ، قابل‌ گسترش. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_b2b_مارکتپلیس_3k_کاربر&quot;&gt;B2B مارکت‌پلیس (3k کاربر)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot تراکنش‌ها بین خریداران و فروشندگان را مدیریت می‌کند (مهم). Supabase باقی موارد را مدیریت می‌کند: پروفایل‌ها، پیام‌رسانی در زمان واقعی، اسناد. این که آنها پایگاه داده PostgreSQL یکسانی را به اشتراک می‌گذارند، ما را از هرگونه همگونی‌سازی پیچیده در امان نگه می‌دارد. بهترین انتخاب معماری که تا به امروز کرده‌ایم. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ترکیب_یک_پارادایم_معماری_مدرن&quot;&gt;ترکیب: یک پارادایم معماری مدرن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری ترکیبی Supabase + Spring Boot یک پارادایم جدید را نشان می‌دهد :&lt;strong&gt;تخصص معماری&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;قدیم پارادایم&quot; #LightCoral {
  card &quot;همه در بک‌اند&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;الگویی جدید&quot; #LightGreen {
  card &quot;Supabase
(آسانی)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot
(تفاضل)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اصول اساسی :&lt;/strong&gt;نه چیزی که به صورت سرویس وجود دارد را بسازید. به آن چیزی که برنامه شما را متمایز می‌کند تمرکز کنید.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قانون_8020&quot;&gt;قانون 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در اکثر برنامه‌ها :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80٪ از operaciones&lt;/strong&gt;CRUD استاندارد هستند → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% از عملیات&lt;/strong&gt;besoins de la logique métier → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Wait I mistakenly left French? No I need Persian translation. Let&amp;#8217;s correct: leading space + &quot;نیاز به منطق کاری دارند&quot; + space + &quot;→&quot; + space + &quot;Spring Boot&quot;. So output: &quot; نیاز به منطق کاری دارند → Spring Boot&quot;. Ensure no extra spaces at end.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Thus final.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نیاز به منطق کاری دارند → Spring Boot&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این قاعده طبیعی معماری هیبرید را توجیه می‌کند&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;توزیع opérations&quot; {

  rectangle &quot;80% - عملیات استاندارد&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - منطق کسب‌وکار&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه_نهایی&quot;&gt;نتیجه نهایی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبرید یک توافقی فنی نیست، این یک&lt;strong&gt;تصمیم استراتژیک&lt;/strong&gt;۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;شما را اجازه می‌دهد که :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ شروع سریع با یک MVP کارآمد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ تأیید بازار خود بدون سرمایه‌گذاری سنگین&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ به تدریج پیش بروید وقتی که پیچیدگی این را می‌طلبد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ هزینه‌های خود را در هر مرحله کنترل کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از بهترین هر فناوری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ از پیش‌انجینری پیش‌زود خودداری کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;انعطاف‌پذیری را برای آینده حفظ کنید&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;نماینده است :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;پراگماتیسم&lt;/strong&gt;: هر فناوری که در آن برتری دارد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;سرعت&lt;/strong&gt;: زمان ورود به بازار کمینه&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پول&lt;strong&gt;اقتصاد&lt;/strong&gt;هزینه‌ها متناسب با ارزش&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;مقیاس‌پذیری&lt;/strong&gt;: معماری که با شما رشد می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;ضبط&lt;/strong&gt;: خدمات معتبر و قابل اعتماد&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_گام_بعدی_شما&quot;&gt;گام بعدی شما&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر این معماری با شما صحبت می‌کند، اینجا جایی است که باید شروع کنید :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;یک حساب Supabase بسازید&lt;/strong&gt;(رایگان)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;طرح داده‌های کمینه خود را تعریف کنید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;احراز هویت OAuth2 را تنظیم کنید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ایجاد کنید اولین صفحه JBake شما که از API استفاده می-conductd را&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;در GitHub Pages استقرار دهید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;شما یک MVP عملکردی در&lt;strong&gt;چند روز&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اسپرینگ بوت به‌طور طبیعی زمانی که به آن نیاز دارید حاضر می‌شود؛ پیش از آن نیست.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;معماری هیبرید، هنر ساختن دقیقاً همان چیزی که لازم است، وقتی که لازم است.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;توسعه موفّق باشید! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;این مقاله را به اشتراک بگذارید اگر فکر می‌کنید که می‌تواند به توسعه‌دهندگان دیگر کمک کند تا انتخاب‌های معماری مناسب انجام دهند.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;زمان خواندن : 12 minutes&lt;/div&gt;
&lt;p&gt;به جای اینکه میان سادگی Supabase و قدرت Spring Boot انتخاب کنید، چرا آن‌ها را ترکیب نمی‌کنید؟ یک معماری هیبریدی را کشف کنید که بهترین ویژگی‌های هر فناوری را به کار می‌گیرد.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;ضرب&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دشواه_جعلی_معماری_مدرن&quot;&gt;دشواه جعلی معماری مدرن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هنگامی که یک برنامه مدرن با frontend ایستا می‌سازیم، اکثر اوقات به یک انتخاب دودویی می‌برسیم:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;هر چیزی را بر روی یک راه‌حل &lt;code&gt;Backend-as-a-Service&lt;/code&gt; متمرکز کنید&lt;/strong&gt;(Supabase, Firebase) - ساده اما محدود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;یک بک‌اند کامل بسازید&lt;/strong&gt;(Spring Boot, Node.js) - قوی اما پیچیده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این انتخاب یک دروغین معضل است. معماری هیبردی یک راه سوم پیشنهاد می‌دهد: &lt;strong&gt;استفاده از هر فناوری جایی که بهتر عمل می‌کند&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دیدگاه_معماری&quot;&gt;دیدگاه معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معماری_سنتی_تکبلوک&quot;&gt;معماری سنتی: تک‌بلوک&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;معماری سنتی&quot; {
  actor Utilisateur as user
  component &quot;فرونت‌اند&quot; as frontend #LightBlue
  component &quot;بک‌اند مونولیتی&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;پایگاه داده&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در این رویکرد، حتی عملیاتی که ساده‌ترین هستند (خواندن یک مقاله، ایجاد یک نظر) باید از طریق backend شما عبور کنند. از اولین روز هزینه پیچیدگی را می‌پردازید.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معمارى_baas_هر_نماینده&quot;&gt;معمارى BaaS : هر نماینده&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;معماری BaaS خالص&quot; {
  actor Utilisateur as user
  component &quot;فرونت‌اند&quot; as frontend #LightBlue
  cloud &quot;سوپربیز / فایربیز&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به‌عکس، واگذاری تمام امور به یک BaaS در آغاز جذاب به‌نظر می‌رسد اما به‌سرعت محدودیت‌هایش را نشان می‌دهد هنگامی که منطق کسب‌وکار پیچیده می‌شود.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معماری_هیبریدی_جداسازی_مسئولیتها&quot;&gt;معماری هیبریدی : جداسازی مسئولیت‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;لایه فرانت‌اند&quot; {
  component &quot;سایت استاتیک JBake&quot; as frontend #SkyBlue
}

package &quot;لایه ساده (Supabase)&quot; #LightGreen {
  component &quot;احراز هویت&quot; as auth
  component &quot;CRUD اصلی&quot; as crud
  component &quot;ذخیره فایل‌ها&quot; as storage
  component &quot;زمان واقعی&quot; as realtime
}

package &quot;لایه کسب‌وکار (Spring Boot)&quot; #Coral {
  component &quot;منطق پیچیده&quot; as logic
  component &quot;آرکسترازی‌ون&quot; as orchestration
  component &quot;وظایف برنامه‌ریزی شده&quot; as jobs
  component &quot;یکپارچه‌سازی‌ها&quot; as integrations
}

database &quot;PostgreSQL اشتراکی&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبرید مسئولیت‌ها را بر اساس پیچیدگی و طبیعت عملیات به‌طور واضح جدا می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مبادئ_طراحی&quot;&gt;مبادئ طراحی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_۱_شروع_ساده_پیشرفت_هوشمندانه&quot;&gt;مبدأ ۱ : شروع ساده، پیشرفت هوشمندانه&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**مرحله 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**مرحله 2 : رشد**&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (اختیاری)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;مرحله ۳ : مقیاس&quot; #LightCoral {
  component &quot;معماری کامل&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اگر به Spring Boot نیاز ندارید، آن را ایجاد نکنید.&lt;/strong&gt;Supabase را شروع کنید؛ Spring Boot را زمانی اضافه کنید که پیچیدگی آن را توجیه کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_۲_جداسازی_بر_پایهٔ_نوع_عملیات&quot;&gt;اصول ۲ : جداسازی بر پایهٔ نوع عملیات&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_3_منبع_یگانه_حقیقت&quot;&gt;مبدأ 3: منبع یگانه حقیقت&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;اسکیما: احراز هویت (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;طرح: عمومی (به اشتراک)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;اسکیما: کسب‌وکار (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;سوپربیس&quot; as supabase #LightGreen
component &quot;اسپرینگ بوت&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;با به اشتراک‌گذاری همان instance PostgreSQL، Supabase و Spring Boot روی داده‌های یکسان کار می‌کنند بدون نیاز به همگام‌سازی پیچیده.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_همگامسازی_جریانها&quot;&gt;همگام‌سازی جریان‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_جریان_1_احراز_هویت_مرکزی&quot;&gt;جریان 1 : احراز هویت مرکزی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;کاربر&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;احراز هویت Supabase&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;ورود&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;نقطه کلیدی&lt;/strong&gt;یک فرآیند احراز هویت، یک JWT، قابل استفاده در هر مکان.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلو_2_همگامسازی_یک_فرآیند_تجاری_پیچیده&quot;&gt;فلو 2 : همگام‌سازی یک فرآیند تجاری پیچیده&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;کلاینت&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase پایگاه داده&quot; as supadb
participant &quot;API Stripe&quot; as stripe
participant &quot;سرویس انبار&quot; as inventory
participant &quot;سرویس ایمیل&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;چه چیزی Spring Boot ارائه می‌دهد&lt;/strong&gt;همگام‌سازی قابل اعتماد از فرآیندهای پیچیده شامل چندین سیستم با تضمین ترنزاکیونی.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_جريان_3_کارها_برنامهریزی_شده_و_همگامسازیها&quot;&gt;جريان 3 : کارها برنامه‌ریزی شده و همگام‌سازی‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;زماندهندهٔ\n(Spring Boot)&quot; as scheduler
participant &quot;سرویس گزارش&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;API خارجی&quot; as api
participant &quot;سرویس ایمیل&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;چه چیزی Spring Boot به ارمغان می‌آورد&lt;/strong&gt;: کارهای برنامه‌ریزی‌شده قابل اعتماد با مدیریت وضعیت، تلاش خودکار و اجرای تضمین‌شده.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ماتریس_تصمیمگیری&quot;&gt;ماتریس تصمیم‌گیری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_supabase_چه_زمانی_استفاده_شود&quot;&gt;Supabase چه زمانی استفاده شود؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_زمان_استفاده_از_spring_boot&quot;&gt;زمان استفاده از Spring Boot؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نمونههای_معماری_بر_اساس_نوع_پروژه&quot;&gt;نمونه‌های معماری بر اساس نوع پروژه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_وبلاگ_نمونهکار&quot;&gt;وبلاگ / نمونه‌کار&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;وبلاگ شخصی - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (رایگان)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (اختیاری)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (اختیاری)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حکم&lt;/strong&gt;: 100% Supabase کافی است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_برنامه_saas&quot;&gt;برنامه SaaS&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;برنامه SaaS - معماری هیبریدی&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;خدمات خارجی&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL مشترک&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حكم&lt;/strong&gt;: معماری هیبریدی لازم است. Supabase برای بخش اصلی، Spring Boot برای بخش حیاتی (پرداخت‌ها، صورتحساب).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تجارت_الکترونیکی&quot;&gt;تجارت الکترونیکی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;تجارت الکترونیک - 70% Spring Boot&quot; {
  component &quot;فروشگاه (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (وظیفهٔ اصلی)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;ادغام‌ها&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (وظیفهٔ اصلی)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حکم&lt;/strong&gt;Spring Boot ضروری. Supabase فقط برای احراز هویت و فهرست.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استراتژی_مهاجرت_تدریجی&quot;&gt;استراتژی مهاجرت تدریجی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_هزینهها_و_ملاحظات_عملیاتی&quot;&gt;هزینه‌ها و ملاحظات عملیاتی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ساختار_هزینهها&quot;&gt;ساختار هزینه‌ها&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;هزین‌های ماهانه تخمینی&quot; {

  rectangle &quot;فاز MVP
(0-1000 users)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;فاز رشد
(1k-10k کاربر)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;مقیاس فاز
(10k-100k کاربر)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;مقیاس فاز
(10k-100k کاربر)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مسئولیتهای_عملیاتی&quot;&gt;مسئولیت‌های عملیاتی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;کی چه کاری را مدیریت می‌کند؟&quot; {

  rectangle &quot;مدیریت توسط Supabase (بدون تلاش)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;مدیریت شده توسط GitHub (بدون تلاش)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;برای مدیریت (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;برای مدیریت (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه_تعادل_کامل&quot;&gt;نتیجه : تعادل کامل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبرید Supabase + Spring Boot یک توافقی نیست، این یک&lt;strong&gt;همکاری&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصولهای_لازم_به_یادداشت&quot;&gt;اصول‌های لازم به یادداشت&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کیبای_این_معماری_را_انتخاب_کنیم&quot;&gt;کیبای این معماری را انتخاب کنیم؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ این معماری برای موارد زیر ایده‌آل است :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;شما می‌خواهید به سرعت شروع کنید (MVP به صورت روز، نه ماه)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما یک افزایش در پیچیدگی کسب‌وکار را پیش‌بینی می‌کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما می‌خواهید هزینه‌های اولیه را به حداقل برسید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما PostgreSQL را دوست دارید و می‌خواهید منبع یکتای حقیقت داشته باشید.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما Kotlin و Coroutines را برای منطق کسب‌وکار دوست دارید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما می‌خواهید از قفل‌گیری کامل فروشنده جلوگیری کنید&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ این معماری برای این شرایط مناسب نیست :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;پروژه شما ساده است و چنین خواهد بود (وبلاگ شخصی → 100٪ Supabase کافی است)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما یک استک بک‌اند پیش‌ساخته دارید که آن را به خوبی می‌دانید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما یک مونولیت سنتی ترجیح می‌دهید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شما به .NET، پایتون یا هر زبان دیگری سمت بک‌اند نیاز دارید.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بینش_نهایی_جامع&quot;&gt;بینش نهایی جامع&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;معماری هیبرید کامل&quot; {

  actor &quot;کاربران&quot; as users

  rectangle &quot;Frontend (استاتیک)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend ساده (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend کاری (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
منبع یکتای حقیقت&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بهترین_دو_جهان&quot;&gt;بهترین دو جهان&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این معماری به شما می‌دهد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 سرعت Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;شروع به ساعت، نه به هفته&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;احراز هویت OAuth2 در چند کلیک&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIهای REST به‌طور خودکار تولید شده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پیکربندی صفر سرور&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 قدرت Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin و Coroutines برای کد ناهمگام زیبا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;همگام‌سازی فرآیندهای کاری پیچیده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کارهای زمان‌بندی شده قابل اعتماد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تراکنش‌های ACID تضمین‌شده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اکوسیستم کامل Spring&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 اقتصاد پیشرو&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ برای شروع و تأیید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;هزینه‌های پیروی از رشد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بدون مهندسی پیش‌زمانه&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 قابلیت معماری&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;مهاجرت تدریجی بدون بازسازی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;افزودن Spring Boot فقط اگر لازم باشد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بدون قفل کامل فروشنده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;معماری تکاملی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_برای_پیش_رفتن&quot;&gt;برای پیش رفتن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_منابع_فنی&quot;&gt;منابع فنی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مستندات Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;راهنمای احراز هویت&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;امنیت سطح سطر&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;APIهای خودکار&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مستندات Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot با کاتلین&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutine‌ها و Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;سرور منبع JWT&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مقالات مکمل :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;امن‌سازی API‌ها با JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بهینه‌سازی عملکرد PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;الگ‌های مهاجرت تدریجی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مدیریت خطاها در معماری توزیع‌شده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مورد_استفاده_واقعی&quot;&gt;مورد استفاده واقعی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این معماری ترکیبی با موفقیت در : استفاده می‌شود&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;سرویس ابری بین‌عامل&lt;/strong&gt;: احراز هویت Supabase, فاکتورینگ Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بازارها&lt;/strong&gt;: كتالوج Supabase، تراکنش‌های Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پلتفرم‌های محتوا&lt;/strong&gt;: مقالات Supabase, analytics Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ابزارهای داخلی&lt;/strong&gt;CRUD Supabase, فرآیندهای کاری Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_لیست_چک_راهاندازی&quot;&gt;لیست چک راه‌اندازی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحلہ 1 - مبانی (هفته 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; ایجاد حساب Supabase - [ ] پروژه PostgreSQL را پیکربندی کنید - [ ] احراز هویت را فعال کنید (Google, GitHub) - [ ] تعریف اسکیمای اولیه - [ ] تنظیم امنیت سطح ردیف - [ ] تست API‌ها از JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحله 2 - MVP (هفته 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; صفحات اصلی را پیاده‌سازی کنید - [ ] احراز هویت OAuth2 را ادغام کنید - [ ] ایجاد فرم‌های CRUD - [ ] ذخیره‌سازی را برای فایل‌ها پیکربندی کنید - [ ] قرار دادن در GitHub Pages - [ ] آزمایش در شرایط واقعی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحله 3 - تکامل (بر اساس نیازها)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; شناسایی نیازهای منطقی پیچیده - [ ] ایجاد پروژه اسپرینگ بوت در صورت لزوم - [ ] تنظیم اعتبارسنجی JWT Supabase - [ ] اتصال به PostgreSQL Supabase - [ ] مهاجرت ویژگی‌های پیچیده - [ ] اجرای کارهای زمان‌بندی‌شده - [ ] پیاده‌سازی Spring Boot (Cloud Run، و غیره)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ضدالگوهایی_که_باید_اجتناب_کرد&quot;&gt;ضدالگوهایی که باید اجتناب کرد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ نکنید:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;داده‌ها را بین Supabase و Spring Boot کپی کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دو پایگاه داده PostgreSQL جداگانه ایجاد کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;احراز هویت را خودتان کد بنویسید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از Spring Boot برای CRUD ساده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;به‌طرز بیش از حد معماری کردن از ابتدا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نادیده‌گیری سطح ردیف امنیت Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بهتر است :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;به اشتراک گذاشتن یک پایگاه داده PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اجازه دهید Supabase احراز هویت را مدیریت کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از Spring Boot فقط برای پیچیدگی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شروع به سادگی، پیشرفت به تدریج&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استفاده از نقاط força هر فناوری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;امن‌سازی با RLS در سطح پایگاه داده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_منظورهای_تکامل&quot;&gt;منظورهای تکامل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افزودن_قابلیتهای_جدید&quot;&gt;افزودن قابلیت‌های جدید&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;معماری فعلی&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;تحولات ممکن&quot; #LightYellow {

  package &quot;عملکرد&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;نظارت&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;ویژگی‌ها&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مقیاسگیری_افقی&quot;&gt;مقیاس‌گیری افقی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هنگامی که برنامه شما بزرگ می‌شود، معماری هیبریدی به طور طبیعی مقیاس‌پذیر می‌شود :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;به صورت خودکار تا میلیون‌های عملیات مقیاس‌پذیر می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas برای عملکرد خواندن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بازیابی نقطه در زمان برای امنیت&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;چندین نمونه پشت یک موزن‌ساز بار&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;طراحی بی‌وضعیت مقیاس‌پذیری افقی را تسهیل می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes برای orchestra­tion در صورت نیاز&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;پارتیشن‌سازی برای جداول حجیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;گروه‌بندی اتصالات (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شاردینگ واقعاً ضروری است (نادر)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_شواهد_معماری&quot;&gt;شواهد معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_کاربران&quot;&gt;Startup SaaS (50k کاربران)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تمام Span‌های کد backtick (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) را به‌صورت دقیق حفظ کنید — هیچ‌گاه محتوای backtick، فاصله یا مکان را تغییر ندهید. این متن ممکن است parçهٔ یک جمله بزرگتر باشد — پارچ را بدون درخواست contextual بیشتر ترجمه کنید. فقط متن ترجمه‌شده را خروجی دهید — بدون توضیح، بدون نظر، بدون مقدمة، بدون گزینش، بدون گزینند. ما 100% Supabase را شروع کردیم. وقتی به 5k کاربر رسیدیم، Spring Boot را فقط برای صورتحساب Stripe و گزارش‌های ماهانه اضافه کردیم. یک سال بعد، 80% از operaciones‑های ما همچنان از طریق Supabase انجام می‌شوند. Spring Boot فقط بخش بحرانی را مدیریت می‌کند. این جداسازی به ما اجازه داد تا بدون بازسازی مقیاس‌پذیری داشته باشیم. &lt;em&gt;__&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پلتفرم_e_learning_10k_کاربر&quot;&gt;پلتفرم E-learning (10k کاربر)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(Empty output) احراز هویت OAuth2 Supabase سه هفته از زمان توسعه ما را به ما صرفه‌جویی کرد. API‌های خودکار تولید شده تمام فهرست دوره‌های ما را مدیریت می‌کنند. Spring Boot فقط برای گواهینامه‌های PDF و ایمیل‌های پیشرفت استفاده می‌شود. معماری ساده، قابل نگهداری و مقیاس‌پذیر. &lt;em&gt;__&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_marketplace_b2b_3k_کاربران&quot;&gt;Marketplace B2B (3k کاربران)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot معاملات بین خریداران و فروشندگان (مهم) را مدیریت می‌کند. Supabase همهٔ بقیه را مدیریت می‌کند: پروفایل‌ها، پیام‌رسانی زمان واقعی، اسناد. اینکه آنها پایگاه داده یکسانی PostgreSQL دارند، نیاز به هم‌سنجازی پیچیده‌ای را رفع می‌کند. بهترین انتخاب معماری که تا کنون کرده‌ایم. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ترکیب_یک_پارادایم_معماری_مدرن&quot;&gt;ترکیب: یک پارادایم معماری مدرن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معماری هیبریدی Supabase + Spring Boot نشان‌دهنده یک پارادایم جدید است :&lt;strong&gt;تخصص معماری&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;قدیمی پارادایم&quot; #LightCoral {
  card &quot;همه در بک‌اند&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;پارادایم جدید&quot; #LightGreen {
  card &quot;Supabase\n(راحتی)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot\n(تفاضل)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اصول اساسی :&lt;/strong&gt;آنچه به صورت یک سرویس وجود دارد را نسازید. تمرکز کنید بر آنچه که برنامه شما را متمایز می‌سازد.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قانون_۸۰۲۰&quot;&gt;قانون ۸۰/۲۰&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در اکثر برنامه‌ها:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% از عملیات&lt;/strong&gt;CRUD استاندارد → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20٪ از عملیات&lt;/strong&gt;نیاز به لوجیک تجاری دارند → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این قاعده طبیعی، معماری هیبریدی را توجیه می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;توزیع عملیات&quot; {

  rectangle &quot;80% - opérations standards
(Actually translation: &quot;80% - opérations standards&quot; should be Persian. Let&#39;s output correctly.)

&amp;lt;/think&amp;gt;

80% - عملیات استاندارد&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - منطق کاری&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه_نهایی&quot;&gt;نتیجه نهایی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معمارای هیبریدی یک تناقض فنی نیست، این یک&lt;strong&gt;تصمیم استراتژیک&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;شما را اجازه می‌دهد تا :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ به سرعت با یک MVP کارآمد شروع کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ بازار خود را بدون سرمایه‌گذاری سنگین تأیید کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ به تدریج پیش بروید وقتی پیچیدگی آن را می‌طلبد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ کنترل هزینه‌های خود را در هر مرحله&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ استفاده بهترین از هر فناوری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ اجتناب از مهندسی بیش از حد زودهنگام&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ حفظ انعطاف‌پذیری برای آینده&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;او نمایانگر است :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;پراگرماتیک&lt;/strong&gt;: هر فناوری که او در آن ماهر است&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;سرعت&lt;/strong&gt;حداقل زمان ورود به بازار&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;اقتصاد&lt;/strong&gt;: هزینه‌ها متناسب با ارزش&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;مقیاس‌پذیری&lt;/strong&gt;معماری که با شما رشد می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️ &lt;strong&gt;قوت&lt;/strong&gt;: خدمات آزمایش‌شده و قابل اعتماد&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_گام_بعدی_شما&quot;&gt;گام بعدی شما&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر این معماری با شما صحبت می‌کند، اینجا جایی است که باید شروع کنید:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;یک حساب Supabase ایجاد کنید&lt;/strong&gt;(رایگان)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اسخیم داده‌های حداقل خود را تعریف کنید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;احراز هویت OAuth2 را پیکربندی کنید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;صفحه JBake اول خود را ایجاد کنید که از API استفاده کند&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;در گیت‌هاب پیج‌ها مستقر شوید&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;شما یک MVP کارآمد خواهید داشت در&lt;strong&gt;چند روز&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot به طور طبیعی وقتی که به آن نیاز دارید خواهد آمد. پیش از آن.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;معماری هیبرید، هنر ساختن دقیقاً آنچه لازم است، زمان لازم است.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;توسعه خوب! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این مقاله را به اشتراک بگذارید اگر فکر می‌کنید می‌تواند به دیگر توسعه‌دهندگان کمک کند تا انتخاب‌های معماری مناسب داشته باشند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_رِزومه&quot;&gt;رِزومه&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مشکل_این_لعنتی_پاپالیsh_tem&quot;&gt;مشکل: این لعنتی پاپالیSh tem&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_یک_کابوس_برای_تجربه_کاربری&quot;&gt;یک کابوس برای تجربه کاربری&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fouc_یک_مشکل_وب_قدیمی&quot;&gt;FOUC: یک مشکل وب قدیمی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تأثیر_بر_ادراک_کیفیت&quot;&gt;تأثیر بر ادراک کیفیت&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تحلیل_فنی_مسئله&quot;&gt;تحلیل فنی مسئله&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_چرا_یک_اسکریپت_کلاسیک_کافی_نیست&quot;&gt;چرا یک اسکریپت کلاسیک کافی نیست؟&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_روشی_حدسی_اما_غیر_مؤثر&quot;&gt;روشی حدسی اما غیر مؤثر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_درک_رویداد_domcontentloaded&quot;&gt;درک رویداد DOMContentLoaded&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مشکل_بلاکینگ_رندر&quot;&gt;مشکل بلاکینگ رندر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نمایش_مسئله&quot;&gt;نمایش مسئله&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تلاشهای_ناکارآمد_برای_حل&quot;&gt;تلاش‌های ناکارآمد برای حل&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_راهحل_واقعی_عمل_زودتر&quot;&gt;راه‌حل واقعی : عمل زودتر&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حل_بارگذاری_زودهنگام_early_loading&quot;&gt;حل: بارگذاری زودهنگام (Early Loading)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_اصلهٔ_اساسی&quot;&gt;اصلهٔ اساسی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_چرا_head_مکان_ایدهآل_است&quot;&gt;چرا &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; مکان ایده‌آل است&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_معماری_حل_در_سه_لایه&quot;&gt;معماری حل در سه لایه&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحله_۱_ذخیرهسازی_انتخاب_کاربر&quot;&gt;مرحله ۱: ذخیره‌سازی انتخاب کاربر&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_localstorage_حافظهی_پایدار_شما&quot;&gt;localStorage: حافظه‌ی پایدار شما&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_پیادهسازی_پشتیبانگیری_از_تم&quot;&gt;پیاده‌سازی پشتیبان‌گیری از تم&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مدیریت_موارد_خطا&quot;&gt;مدیریت موارد خطا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_استراتژیهای_پیشرفته_پایداری&quot;&gt;استراتژی‌های پیشرفته پایداری&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحله_2_اسکریپت_بارگذاری_preloud_در_head&quot;&gt;مرحله 2 : اسکریپت بارگذاری Preloud در `&amp;lt;head&amp;gt;&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_قلب_راهحل&quot;&gt;قلب راه‌حل&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ساختار_اسکریپت_هر_خط_مهم_است&quot;&gt;ساختار اسکریپت : هر خط مهم است&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تشخیص_ترجیح_سیستم_بهعلاوه&quot;&gt;تشخیص ترجیح سیستم (به‌علاوه)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_عملکرد_چرا_این_اسکریپت_سریع_است&quot;&gt;عملکرد: چرا این اسکریپت سریع است&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_قرارگیری_بهینه_در_head&quot;&gt;قرارگیری بهینه در `&amp;lt;head&amp;gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحله_3_قدرت_انتخابکنندههای_attribut_css&quot;&gt;مرحله 3 : قدرت انتخاب‌کننده‌های attribut CSS&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_سیستم_تم_bootstrap_5&quot;&gt;سیستم تم Bootstrap 5&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ساختار_css_برای_یک_سیستم_تم&quot;&gt;ساختار CSS برای یک سیستم تم&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_رِزومه&quot;&gt;رِزومه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در این مقاله فنی عمیق، ما بررسی می‌کنیم چگونه می‌توانیم یک انتخاب‌کننده تم (light/dark) را بدون افکت چشمک‌زن نامطلوب که در زمان بارگذاری صفحه رخ می‌دهد، پیاده‌سازی کنیم. ما به‌طور جزئی چرخهٔ رندر مرورگر را تحلیل می‌کنیم، عوامل عمیق FOUC (Flash of Unstyled Content) را بررسی می‌کنیم و یک راه‌حل قوی مبتنی بر پیش‌بارگذاری همزمان در`&amp;lt;head&amp;gt;`. این تکنیک تجربه کاربر را روان و حرفه‌ای تضمین می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مشکل_این_لعنتی_پاپالیsh_tem&quot;&gt;مشکل: این لعنتی پاپالیSh tem&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یک_کابوس_برای_تجربه_کاربری&quot;&gt;یک کابوس برای تجربه کاربری&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سیناريو را تصور کنید: شما ساعت‌ها را صرف کردید تا یک تم تاریک زیبا برای برنامه وب خود طراحی کنید. رنگ‌ها به完美 manera متوازن‌اند، تضاد بهینه است و کاربران شما این گزینه را دوست دارند. اما مشکلی خجالت‌انگیز وجود دارد: در هر بار بارگذاری صفحه، برای یک قسمت از ثانیه، تم روشن پیش‌فرض نمایش داده می‌شود قبل از اینکه تم تاریک جایگزین شود.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این &quot;flash&quot; بصری، اگرچه کوتاه باشد (گاهی کمتر از ۱۰۰ میلی‌ثانیه)، بلافاصله توسط چشم انسان قابل‌درک است و تجربه‌ای ناخوشایند به‌وجود می‌آورد. برای کاربران که به‌دلیل راحتی بصری یا قابلیت دسترسی تم تاریک را انتخاب کرده‌اند، این چشمک‌زدن می‌تواند حتی دردناک باشد، به‌ویژه در محیطی با نور ضعیف.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fouc_یک_مشکل_وب_قدیمی&quot;&gt;FOUC: یک مشکل وب قدیمی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این پدیده یک گونه از چیزی است که آن را &quot;Flash of Unstyled Content&quot; (FOUC) می‌نامند، یک مشکل کلاسیک در توسعه وب که از روزهای اولیه CSS برمی‌گردد. FOUC هنگامی رخ می‌دهد که مرورگر موقتاً محتوای HTML را بدون اعمال استایل‌های CSS نمایش می‌دهد، که منجر به نمایش موقت محتوای بدون استایل می‌شود.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در مورد مورد خاص ما، ما دربارهٔ محتوایی که به‌طور کامل بدون استایل نیست، صحبت نمی‌کنیم، بلکه دربارهٔ یک&lt;strong&gt;فلاش teme اشتباه&lt;/strong&gt;(FOWT) - محتوا استایل داده شده است، اما با تم نادرست. این به ویژه ناراحت کننده است زیرا نشان می‌دهد که برنامه ما &quot;فراموش می‌کند&quot; ترجیح کاربر را در هر بار بارگذاری صفحه.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تأثیر_بر_ادراک_کیفیت&quot;&gt;تأثیر بر ادراک کیفیت&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این مشکل، اگرچه تکنیکی است، پیامدهای مهمی بر ادراک کیفیت برنامه شما دارد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;کاهش لک&lt;/strong&gt;لمعان این احساس را به وجود می‌آورد که برنامه ناقص یا بهینه‌سازی نشده باشد. کاربران عموماً این نقص‌های بصری کوچک را ناتوانی کلی در حرفه‌ای بودن مرتبط می‌دانند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;شکستگی همبستگی&lt;/strong&gt;برنامه به‌نظر می‌رسد ترجیحات کاربر را «فراموش» می‌کند و احساس ناهم‌خوانی بین رابط و انتظارات ایجاد می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;خستگی بصری&lt;/strong&gt;برای کاربران حساس به نور یا مبتلا به میگرن، این فلش نورانی می‌تواند بیش از یک ناراحتی ظاهری ساده باشد.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;عملکرد ادراکی&lt;/strong&gt;به‌طرز عجیب، حتی اگر وب‌سایت شما به سرعت بارگذاری شود، این لمعان می‌تواند الإحاء دهد که برنامه‌ای کند یا غیر پاسخگو است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تحلیل_فنی_مسئله&quot;&gt;تحلیل فنی مسئله&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای درک اینکه چگونه این مشکل را حل کنیم، باید ابتدا بفهمیم چرا این مشکل رخ می‌دهد. تپش به دلیل تاخیر زمانی بین سه رویداد کلیدی در چرخه زندگی یک صفحه وب رخ می‌دهد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پارس اولیه HTML&lt;/strong&gt;: مرورگر ساختار صفحه شما را می‌خواند و تجزیه می‌کند.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اعمال استایل‌های CSS&lt;/strong&gt;: مرورگر قوانین CSS را اعمال می‌کند و rendering بصری را محاسبه می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اجرای JavaScript&lt;/strong&gt;: کد شما که تم را تغییر می‌دهد اجرا می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مشکل زمانی پیش می‌آید که رویداد شماره ۳ (اجرا کردن جاوااسکریپت) پس از آن رخ می‌دهد که مرورگر پیش‌تر شروع یا پایان رویداد شماره ۲ (اعمال استایل‌ها) را داشته باشد. در این لحظه، مرورگر قبلاً تصمیم گرفته است کدام تم را نمایش دهد و کد شما به دیرستی می‌رسد تا بتواند پیش از رندر اول آن را تحت تأثیر قرار دهد.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_چرا_یک_اسکریپت_کلاسیک_کافی_نیست&quot;&gt;چرا یک اسکریپت کلاسیک کافی نیست؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_روشی_حدسی_اما_غیر_مؤثر&quot;&gt;روشی حدسی اما غیر مؤثر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;راه‌حل طبیعی‌ترین برای یک توسعه‌دهنده این بود که یک اسکریپت را در پایان ما`&amp;lt;body&amp;gt;`که تم ترجیحی کاربر را بررسی کرده و آن را اعمال می‌کند. این رویکرد به روش‌های سنتی بهتر وب پایبند است که بارگذاری اسکریپت‌ها در انتهای صفحه را پیشنهاد می‌دهند تا رندر مسدود نشود.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// À la fin de &amp;lt;body&amp;gt; - L&#39;APPROCHE INSUFFISANTE
document.addEventListener(&#39;DOMContentLoaded&#39;, () =&amp;gt; {
  const theme = localStorage.getItem(&#39;preferred-theme&#39;);
  if (theme === &#39;dark&#39;) {
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
  }
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این رویکرد در نگاه اول منطقی به نظر می‌رسد. ما صبر می‌کنیم تا DOM آماده شود، سپس تم را اعمال می‌کنیم. ساده، نیست؟ متأسفانه، این سادگی یک عیب اساسی مربوط به زمان‌بندی چرخه رندر مرورگر را پنهان می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_درک_رویداد_domcontentloaded&quot;&gt;درک رویداد DOMContentLoaded&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;رویداد`DOMContentLoaded`در زمان بارگذاری کامل و تجزیه سند HTML اولیه توسط مرورگر آغاز می‌شود&lt;strong&gt;بدون انتظار&lt;/strong&gt;پایان بارگذاری استایل‌ها، تصاویر و زیر-چارچوب‌ها. این یک نکته مهم برای درک است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این دنبالهٔ عادی رویدادها :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;مرورگر شروع به دانلود HTML می‌کند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او HTML را به محض دریافت آن تجزیه و تحلیل می‌کند.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او برچسب‌ها را می‌یابد`&amp;lt;link&amp;gt;`برای CSSها و شروع به دانلودشان کنید&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او برچسب‌ها را می‌یابد.`&amp;lt;script&amp;gt;`و آن‌ها را اجرا می‌کند (بر اساس نوع و ویژگی‌هایشان)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او DOM (Document Object Model) را می‌سازد.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;رویداد &lt;code&gt;DOMContentLoaded&lt;/code&gt; راه‌اندازی می‌شود&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او همچنان استایل‌ها را اعمال می‌کند و چیدمان را انجام می‌دهد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اولین paint (نمایش) رخ می‌دهد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;رویداد`load`وقتی که تمام منابع بارگذاری شده‌اند، اجرا می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مسئله؟ بین مرحله ۶ (DOMContentLoaded) و مرحله ۸ (premier paint)، مرورگر تصمیمات خود را درباره نحوه نمایش صفحه گرفته است. اگر اسکریپت تغییر تم شما در مرحله ۶ اجرا شود، هم‌اکنون بیش از حد دیر شده است تا یک نمایش اولیه با سبک‌های پیش‌فرض را جلوگیری کنید.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مشکل_بلاکینگ_رندر&quot;&gt;مشکل بلاکینگ رندر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در واقع، زمان‌بندی حتی پیچیده‌تر است. مرورگرهای مدرن از تکنیک‌های بهینه‌سازی پیچیده برای بهبود عملکرد ادراکی استفاده می‌کنند. سعی می‌کنند اولین Paint (First Contentful Paint) را به سرعت‌ترین شکل ممکن انجام دهند تا کاربر چیزی روی صفحه ببیند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CSS به طور پیش‌فرض &quot;render-blocking&quot; هستند، یعنی مرورگر صبر می‌کند تاStylesheet‌ها را دانلود و پارس کند قبل از اولین paint. این منطقی است: ما نمی‌خواهیم محتوایی بدون استایل نمایش دهیم.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اما اینجا فخ است: هنگامی که مرورگر این استایل‌های CSS را برای اولین بار اعمال می‌کند، او این کار را بر اساس وضعیت فعلی DOM انجام می‌دهد. اگر ویژگی`data-bs-theme`هنوز برچسب آن تعریف نشده است.&lt;code&gt;&amp;lt;html&amp;gt;&lt;/code&gt;, مرورگر استایل‌های پیش‌فرض را اعمال می‌کند (معمولاً تم روشن).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سپس، وقتی اسکریپت شما اجرا می‌شود و این ویژگی را تغییر می‌دهد، مرورگر باید:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;باز محاسبه تمام استایل‌های متأثر از این تغییر&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بازسازی چیدمان در صورت نیاز&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;عناصر تحت تأثیر را دوباره رنگ بندی کنید&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این فرآیند محاسبه مجدد و رنگ‌پخش آن است که باعث چشمک‌زدن مرئی می‌شود.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نمایش_مسئله&quot;&gt;نمایش مسئله&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای درک بهتر این دنباله مشکل‌دار، یک نمودار دنباله دقیق را بررسی می‌کنیم:&lt;/p&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-flux-incorrect&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Utilisateur
participant Navigateur
participant &quot;پارسر HTML&quot; as Parser
participant &quot;مدل شیء CSS&quot; as CSS
participant &quot;Script.js (پایان body)&quot; as Script
participant &quot;موتور رندر&quot; as Render

Utilisateur -&amp;gt; Navigateur: Demande la page
activate Navigateur

Navigateur -&amp;gt; Parser: Parse le HTML
activate Parser
Parser -&amp;gt; CSS: Découvre et charge les CSS
activate CSS
Parser -&amp;gt; Parser: Construit le DOM
Parser -&amp;gt; Navigateur: DOM Ready (DOMContentLoaded)
deactivate Parser

CSS -&amp;gt; CSS: Parse les feuilles de style
CSS -&amp;gt; Render: CSSOM Ready
deactivate CSS

activate Render
Render -&amp;gt; Render: Calcule les styles avec data-bs-theme=&quot;&quot;note right: موضوع پیش‌فرض (روشن)
Render -&amp;gt; Navigateur: Paint اولین (موضوع روشن)
note right: کاربر تم روشن را می‌بیند
deactivate Render

Navigateur -&amp;gt; Script: اسکریپت را اجرا می‌کند
activate Script
Script -&amp;gt; Script: localStorage را می‌خواند
Script -&amp;gt; Navigateur: setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;)
deactivate Script

activate Render
Render -&amp;gt; Render: استایل‌ها را با data-bs-theme= محاسبه می‌کند&quot;dark&quot;
note right: Thème sombre
Render -&amp;gt; Navigateur: Repaint (Thème Sombre)
note right: Clignotement visible
deactivate Render

deactivate Navigateur
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این نمودار واضحاً problème را نشان می‌دهد: اولین paint قبل از اینکه اسکریپت ما فرصت داشته باشد تم مناسب را تنظیم کند، رخ می‌دهد. paint بعدی که رخ می‌دهد، لمعان قابل‌توجه را ایجاد می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تلاشهای_ناکارآمد_برای_حل&quot;&gt;تلاش‌های ناکارآمد برای حل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برخی روش‌ها برای حل این مشکل امتحان شده‌اند، اما اکثر آن‌ها معایب خاص خود را دارند:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;رویکرد ۱: پنهان کردن محتوا تا بارگذاری&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;body {
  opacity: 0;
  transition: opacity 0.3s;
}

body.loaded {
  opacity: 1;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این رویکرد تمام محتوا را تا زمانی که جاوااسکریپت-theme مناسب را تنظیم نکرده باشد، پنهان می‌کند. مشکل؟ این کار به‌طور مصنوعی نمایش محتوا را به تعویق می‌اندازد، که باعث می‌شود سایتی کندتر به نظر برسد. علاوه بر این، اگر جاوااسکریپت غیرفعال باشد، کاربر چیزی را نخواهد دید!&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;روش 2 : استفاده از loader/spinner&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثل رویکرد ۱، اما با یک spinner بارگذاری. این مشکل را پنهان می‌کند اما عملکرد واقعی را بهبود نمی‌دهد و یک تأخیر محسوس بی‌معنی اضافه می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;روش 3: پیش‌فرض به تم تاریک&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برخی توسعه‌دهندگان تم تیره را به‌عنوان پیش‌فرض در CSS تعریف می‌کنند. این موجب می‌شود تا برای کاربران تم تیره، لمعان جلوگیری شود، اما مشکل معکوسی را برای کاربران تم روشن ایجاد می‌کند!&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هیچ‌یک از این رویکردهاacceptable نیستند زیرا علائم را به جای علت ریشه‌ای درمان می‌کنند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_راهحل_واقعی_عمل_زودتر&quot;&gt;راه‌حل واقعی : عمل زودتر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کلید برای حل این مشکل این است که متوجه شویم باید ویژگی را تعریف کنیم`data-bs-theme` &lt;strong&gt;پیش&lt;/strong&gt;که مرورگر شروع به اعمال استایل‌های CSS نکند. این به این معناست که اسکریپت ما باید در دورهٔ زندگی صفحه زودتر اجرا شود، و دقیقاً این چیزی است که در بخش بعدی به بررسی آن می‌پردازیم.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حل_بارگذاری_زودهنگام_early_loading&quot;&gt;حل: بارگذاری زودهنگام (Early Loading)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصلهٔ_اساسی&quot;&gt;اصلهٔ اساسی&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;حل شایستگی به مشکل چشمک زدن ما بر یک اصل ساده ولی قدرتمند است :&lt;strong&gt;همگام‌سازی وضعیت برنامه با فرآیند نمایش مرورگر&lt;/strong&gt;. به‌جای انتظار برای بارگذاری صفحه تا تم را تنظیم کنیم، باید آن را تنظیم کنیم&lt;strong&gt;در حالی که&lt;/strong&gt;بارگذاری، حتی پیش از اینکه استایل‌های CSS اعمال شوند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این روش به &quot;Early Loading&quot; یا &quot;Synchronous Preloading&quot; در اصطلاح توسعه وب شناخته می‌شود. ایده این است که منطق تشخیص تم ما را به زودی‌ترین ممکن در دورة زندگی صفحه اجرا کنیم، به طور ایده‌آل داخل تگ`&amp;lt;head&amp;gt;`, قبل از اینکه مرورگر شروع به دانلود فایل‌های CSS کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_چرا_head_مکان_ایدهآل_است&quot;&gt;چرا &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; مکان ایده‌آل است&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le `&amp;lt;head&amp;gt;`یک اسناد HTML به صورت توالی توسط مرورگر پردازش می‌شود، از بالا به پایین. هر element در ترتیب ظاهر شدن پردازش می‌شود. این ویژگی برای راه‌حل ما بسیار مهم است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وقتی مرورگر یک برچسب را می‌بیند`&amp;lt;script&amp;gt;`در`&amp;lt;head&amp;gt;`بدون ویژگی‌ها`async` ou &lt;code&gt;defer&lt;/code&gt;, il :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پارس کردن HTML را متوقف می‌کند&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اسکریپت را دانلود کن&lt;/strong&gt;(اگر خارجی) یا تخت (به‌صورت inline)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اسکریپت را فوراً اجرا کن&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تجدید پردازش HTML&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این رفتار، اغلب به‌عنوان یک مشکل عملکرد در نظر گرفته می‌شود (از این رو پیشنهاد عادی قرار دادن اسکریپت‌ها در انتهای صفحه است)، در این حالت دقیق، حامی ما می‌شود. با قرار دادن اسکریپت تشخیص تم ما در ابتدای`&amp;lt;head&amp;gt;`, ما تضمین می‌کنیم که قبل از اینکه مرورگر به تگ‌ها برسد، اجرا شود`&amp;lt;link&amp;gt;`قالbهاي‍‍‌سب‍‍ک‌مان.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معماری_حل_در_سه_لایه&quot;&gt;معماری حل در سه لایه&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;راه‌حل کامل ما شامل سه لایه وابسته به یکدیگر است که هر یک نقش خاصی دارد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;لایه 1 : Persistence (localStorage)&lt;/strong&gt; این لایه مسئول ذخیره‌سازی و بازیابی انتخاب کاربر بین جلسات است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;لایه ۲: همگام‌سازی زودهنگام (اسکریپت درونخطی در &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;)&lt;/strong&gt; این لایه وضعیت برنامه را با DOM قبل از رندر اولیه همگام‌سازی می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;لایه 3 : استایل‌های واکنش‌گرا (CSS با انتخابگرهای ویژگی)&lt;/strong&gt; این لایه سبک‌های بصری را بر اساس حالتی که توسط لایه ۲ تعریف شده است، تعریف می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اکنون هر لایه را به‌صورت تفصیلی بررسی می‌کنیم.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحله_۱_ذخیرهسازی_انتخاب_کاربر&quot;&gt;مرحله ۱: ذخیره‌سازی انتخاب کاربر&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_localstorage_حافظهی_پایدار_شما&quot;&gt;localStorage: حافظه‌ی پایدار شما&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le &lt;code&gt;localStorage`یک API ذخیره‌سازی وب است که اجازه می‌دهد جفت‌های کلید-مقدار را به‌صورت پایدار در مرورگر ذخیره کند. برعکس کوکی‌ها، داده‌های`localStorage&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;هرگز به سرور به‌صورت خودکار ارسال نمی‌شوند.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;یک ظرفیت ذخیره‌سازی بزرگ‌تر دارند (معمولاً 5-10 مگابایت)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تاریخ انقضا ندارند (تا زمان حذف صریح پابرجاست)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;به پروتکل و دامنه محدود می‌شوند (Same-Origin Policy)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای مورد استفاده ما، le`localStorage`عالی است چون :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ما نیازی به اشتراک‌گذاری این اطلاعات با سرور نداریم.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ما می‌خواهیم ترجیح به‌صورت نامحدود ادامه یابد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;حجم ذخیره‌سازی مورد نیاز بسیار کم است (چند بایت)&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پیادهسازی_پشتیبانگیری_از_تم&quot;&gt;پیاده‌سازی پشتیبان‌گیری از تم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این چگونه انتخاب کاربر را هنگام تغییر تم ذخیره می‌کنیم :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// Fonction complète pour changer le thème
function setTheme(newTheme) {
  // Validation de l&#39;entrée
  if (![&#39;light&#39;, &#39;dark&#39;, &#39;auto&#39;].includes(newTheme)) {
    console.error(&#39;Thème invalide:&#39;, newTheme);
    return;
  }

  try {
    // Sauvegarde dans localStorage
    localStorage.setItem(&#39;preferred-theme&#39;, newTheme);

    // Application immédiate dans le DOM
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

    // Dispatch d&#39;un événement personnalisé pour notifier d&#39;autres composants
    window.dispatchEvent(new CustomEvent(&#39;theme-changed&#39;, {
      detail: { theme: newTheme }
    }));

    console.log(&#39;Thème changé:&#39;, newTheme);
  } catch (error) {
    console.error(&#39;Erreur lors de la sauvegarde du thème:&#39;, error);
    // Fallback : on applique quand même le thème visuellement
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);
  }
}

// Exemple d&#39;utilisation avec un bouton
document.getElementById(&#39;theme-toggle&#39;).addEventListener(&#39;click&#39;, () =&amp;gt; {
  const currentTheme = document.documentElement.getAttribute(&#39;data-bs-theme&#39;) || &#39;light&#39;;
  const newTheme = currentTheme === &#39;light&#39; ? &#39;dark&#39; : &#39;light&#39;;
  setTheme(newTheme);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مدیریت_موارد_خطا&quot;&gt;مدیریت موارد خطا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مهم است که مواردی که &amp;#8230;&amp;#8203; را مدیریت کنیم`localStorage`موجود نیست یا قابل دسترسی نیست. چند سناریو می‌تواند مانع دسترسی به شود`localStorage`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ناوبری خصوصی سخت&lt;/strong&gt;: Safari در حالت مرور خصوصی یک استثنا ایجاد می‌کند`QuotaExceededError`در حین تلاش‌ها برای نوشتن در`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;تنظیمات حریم خصوصی&lt;/strong&gt;برخی مرورگرها یا افزونه‌های حریم خصوصی ممکن است دسترسی به را مسدود کنند`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;محدودیت‌های دامنه&lt;/strong&gt; : Le `localStorage`در پروتکل قابل دسترسی نیست`file://`در برخی مرورگرها.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فضای ذخیره‌سازی اشباع شده&lt;/strong&gt;اگرچه نادر است، فضای ذخیره‌سازی می‌تواند به‌طور کامل پر شود.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به همین دلیل کد ما از یک بلوک استفاده می‌کند.`try&amp;#8230;&amp;#8203;catch`برای مدیریت این موارد به‌صورت لطف‌آمیز، با ادامهٔ ارائهٔ ویژگی تغییر تم حتی وقتی پایداری موجود نباشد.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استراتژیهای_پیشرفته_پایداری&quot;&gt;استراتژی‌های پیشرفته پایداری&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای برنامه‌های پیچیده‌تر، می‌توانید استراتژی‌های بیشتری در نظر بگیرید :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;همگام‌سازی سرور (اختیاری)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;async function setTheme(newTheme) {
  // Sauvegarde locale immédiate
  localStorage.setItem(&#39;preferred-theme&#39;, newTheme);
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

  // Synchronisation serveur en arrière-plan (si l&#39;utilisateur est connecté)
  if (userIsAuthenticated()) {
    try {
      await fetch(&#39;/api/user/preferences&#39;, {
        method: &#39;POST&#39;,
        headers: { &#39;Content-Type&#39;: &#39;application/json&#39; },
        body: JSON.stringify({ theme: newTheme })
      });
    } catch (error) {
      console.warn(&#39;Échec de la synchronisation serveur:&#39;, error);
      // L&#39;échec n&#39;est pas critique car la préférence est déjà sauvegardée localement
    }
  }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این روش امکان همگونی ترجیحات بین دستگاه‌ها برای کاربران متصل را فراهم می‌آورد، در حالی که واکنش‌پذیری محلی فوری را حفظ می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحله_2_اسکریپت_بارگذاری_preloud_در_head&quot;&gt;مرحله 2 : اسکریپت بارگذاری Preloud در `&amp;lt;head&amp;gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قلب_راهحل&quot;&gt;قلب راه‌حل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اینجا است که جادو به‌طور واقعی کار می‌کند. ما یک اسکریپت کوچک قرار می‌دهیم.&lt;strong&gt;انلاین&lt;/strong&gt;مستقیماً در ماست`&amp;lt;head&amp;gt;`, تمام برچسبهای ما`&amp;lt;link&amp;gt;`قالب‌های استایل. این اسکریپت به‌طور عمدی به‌سادگی، خودمختار و برای اجرا به سرعت حداکثر ممکن طراحی شده است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html lang=&quot;fr&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;
    &amp;lt;title&amp;gt;Mon Site Incroyable&amp;lt;/title&amp;gt;

    &amp;lt;!-- ==========================================
         NOTRE SCRIPT MAGIQUE DE PRÉ-CHARGEMENT
         Ce script DOIT être le premier élément
         dans le &amp;lt;head&amp;gt; après les meta tags
         ========================================== --&amp;gt;
    &amp;lt;script&amp;gt;
      // IIFE pour ne pas polluer le scope global
      (function() {
        &#39;use strict&#39;;

        try {
          // Lecture de la préférence sauvegardée
          const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);

          // Si une préférence existe, on l&#39;applique immédiatement
          if (savedTheme) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
          }
          // Optionnel : Détecter la préférence système si aucune sauvegarde
          else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
          }
          // Sinon, le thème par défaut du CSS sera utilisé (généralement &#39;light&#39;)

        } catch (error) {
          // En cas d&#39;erreur (localStorage bloqué, etc.), on log discrètement
          // et on laisse le thème par défaut s&#39;appliquer
          console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
        }
      })();
    &amp;lt;/script&amp;gt;
    &amp;lt;!-- FIN DU SCRIPT MAGIQUE --&amp;gt;

    &amp;lt;!-- Les feuilles de style sont chargées APRÈS le script --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/bootstrap.min.css&quot;&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/styles.css&quot;&amp;gt;

    &amp;lt;!-- Autres ressources du head --&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;!-- Contenu de la page --&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ساختار_اسکریپت_هر_خط_مهم_است&quot;&gt;ساختار اسکریپت : هر خط مهم است&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ب질을 کنیم این اسکریپت را خط به خط برای درک هر ديزاین設計 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;IIFE (عبارت تابعی بلافاصله فراخوانی می‌شود)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;(function() {
  // ...
})();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این ساختار یک تابع را ایجاد می‌کند که بلافاصله اجرا می‌شود. چرا؟ برای جداسازی متغیرهای ما در یک حوزه محلی و جلوگیری از آلودهٔ حوزه سراسری. حتی اگر ما فقط`const`(که یک حوزة بلوک دارد)، IIFE یک روش خوب است که intentions ما را واضح می‌کند و در برابر تداخل‌های احتمالی نام‌ها محافظت می‌کند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حالت سخت‌گیرانه&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;&#39;use strict&#39;;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;in directive faal mikonad hale sakhtgirane javascrippt ra, ke : - استفاده از متغیرهای غیر اعلام‌شده را ممنوع می‌کند - خطا برای عملیات‌های خطرناک ایجاد کن - بهبود عملکرد در برخی موتورهای JavaScript&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;برای یک اسکریپت حساس مثل این، ما امنیت حداکثر را می‌خواهیم.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بلوک try&amp;#8230;&amp;#8203;catch&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;try {
  // Code principal
} catch (error) {
  console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این بلوک به‌طور کلی ضروری است. مطمئن می‌سازد که اگر چیزی به‌خوبی نرود (localStorage مسدود، خطای غیرممکن در سینتکس و غیره)، اسکریپت ما بارگذاری کامل صفحه را مسدود نخواهد کرد. استفاده از`console.warn`به جای`console.error`نشان می‌دهد که این یک مشکل غیر بحرانی است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;خواندن localStorage&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این خط می‌تواند در برخی موارد (حالت خصوصی سخت Safari) یک استثنا بزند. به همین دلیل آن را در یک بلوک try&amp;#8230;&amp;#8203;catch قرار داده‌ایم.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;برنامه شرطی&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;if (savedTheme) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ما تم را فقط در صورت یافتن تم ذخیره‌شده اعمال می‌کنیم؛ در غیر این صورت، به CSS اجازه می‌دهیم تا از تم پیش‌فرض خود استفاده کند. این روش قوی‌تر از یک مقدار پیش‌فرض کد شده در JavaScript است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تشخیص_ترجیح_سیستم_بهعلاوه&quot;&gt;تشخیص ترجیح سیستم (به‌علاوه)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یک بهبود اختیاری اما شایسته این است که تم ترجیح کاربر را از سیستم عامل او تشخیص دهید، در صورتی که او هنوز در برنامه شما گزینش صریحی نکرده باشد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این ویژگی از Media Query استفاده می‌کند.`prefers-color-scheme`برای پرس و جو از سیستم. در macOS، Windows 10+، iOS و اندروید مدرن، این درخواست ترجیح سیستمی کاربر را برمی‌گرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مزایا :&lt;/strong&gt; - تجربه سفارشی از اولین بازدید - سازگاری با محیط سیستم کاربر - هیچ ذخیره‌سازی لازم برای اولین بازدید نیست&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ملاحظات :&lt;/strong&gt; - همهٔ مرورگرها این ویژگی را پشتیبانی نمی‌کنند (اما پشتیبانی از آن از 2020 عالی است) - بررسی`window.matchMedia`سازگاری را تضمین می‌کند - کاربر می‌تواند این گزینه را همیشه بازنویسی کند&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عملکرد_چرا_این_اسکریپت_سریع_است&quot;&gt;عملکرد: چرا این اسکریپت سریع است&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اسکریپت پیش‌بارگذاری ما به گونه‌ای طراحی شده است که بسیار سریع باشد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اندازه حداقل&lt;/strong&gt;: حدود 300 بایت غیر-minified، 200 بایت minified. این مقدار ضعیف است در مقایسه با هر تصویر یا کتابخانه JavaScript.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;به صورت خطی&lt;/strong&gt;: هیچ درخواست HTTP اضافی وجود ندارد. اسکریپت در HTML است، بنابراین بلافاصله در دسترس است.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;عملیات همگام ساده&lt;/strong&gt;: خواندن یک کلید در localStorage (عملیهٔ فوق‌العاده سریع) و تغییر یک ویژگی DOM (عملیهٔ مرورگر).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;هیچ وابستگی&lt;/strong&gt;: هیچ فریم‌ورک، هیچ کتابخانه، فقط جاوااسکریپت وانیل. هیچ زمان استارت‑اپ، هیچ پارсинг وابستگی.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اجرا یک‌بار&lt;/strong&gt;: این اسکریپت فقط یک بار در زمان بارگذاری اجرا می‌شود. هیچ listener رویدادی، هیچ حلقه، هیچ محاسبه پیچیده‌ای ندارد.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در عمل، روی سخت‌افزار مدرن، این اسکریپت در کمتر از 1 میلی‌ثانیه اجرا می‌شود؛ زمان نامحسوسی که هیچ تاثیری بر عملکرد بارگذاری صفحه ندارد.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قرارگیری_بهینه_در_head&quot;&gt;قرارگیری بهینه در `&amp;lt;head&amp;gt;&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ترتیب عناصر در`&amp;lt;head&amp;gt;`مهم است. این ترتیب پیشنهادی است :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;head&amp;gt;
    &amp;lt;!-- 1. Métadonnées critiques --&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;

    &amp;lt;!-- 2. Notre script de pré-chargement (IMMÉDIATEMENT après les meta) --&amp;gt;
    &amp;lt;script&amp;gt;
      (function() { /* notre code */ })();
    &amp;lt;/script&amp;gt;

    &amp;lt;!-- 3. Titre de la page --&amp;gt;
    &amp;lt;title&amp;gt;Mon Site&amp;lt;/title&amp;gt;

    &amp;lt;!-- 4. Feuilles de style --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;styles.css&quot;&amp;gt;

    &amp;lt;!-- 5. Autres ressources (fonts, favicons, etc.) --&amp;gt;
    &amp;lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.googleapis.com&quot;&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;

    &amp;lt;!-- 6. Autres scripts avec defer ou async --&amp;gt;
    &amp;lt;script src=&quot;app.js&quot; defer&amp;gt;&amp;lt;/script&amp;gt;
&amp;lt;/head&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این دستور ضمانت می‌دهد که:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Charset قبل از پردازش متنی تعریف می‌شود.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اسکریپت ما پیش از بارگذاری CSS اجرا می‌شود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CSSها پس از بارگذاری، مستقیماً تم مناسب را اعمال می‌کنند&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;منابع غیر بحرانی دیگر در آخر بارگذاری می‌شوند&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحله_3_قدرت_انتخابکنندههای_attribut_css&quot;&gt;مرحله 3 : قدرت انتخاب‌کننده‌های attribut CSS&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیستم_تم_bootstrap_5&quot;&gt;سیستم تم Bootstrap 5&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bootstrap 5 یک سیستم زیبای مدیریت تم‌ها مبتنی بر ویژگی‌های سفارشی CSS (متغیرهای CSS) و انتخابگرهای ویژگی‌ها را معرفی کرده است. این سیستم از ویژگی`data-bs-theme`بر روی عنصر`&amp;lt;html&amp;gt;`برای تعیین کدام مجموعه از متغیرهای رنگ باید اعمال شود.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;زیبای این سیستم در سادگی آن نهفته است: به جای بارگذاری استایل‌شیت‌های مختلف یا toggle کلاس‌ها بر روی هزاران عنصر، ما صرفاً یک ویژگی را در یک عنصر تغییر می‌دهیم و CSS به‌دلیل بقASCADE، بقیه را انجام می‌دهد.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ساختار_css_برای_یک_سیستم_تم&quot;&gt;ساختار CSS برای یک سیستم تم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در اینجا یک ساختار CSS کامل برای پیاده‌سازی یک سیستم طرح/theme مقاوم آورده شده است:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;/**
 * SYSTÈME DE THÈME COMPLET
 * Utilise les Custom Properties CSS pour une maintenance facile
 */

/* ============================================
   THÈME PAR DÉFAUT (LIGHT)
   Défini sur :root pour être le fallback
   ============================================ */
:root {
  /* Couleurs de base */
  --color-primary: #0d6efd;
  --color-secondary: #6c757d;
  --color-success: #198754;
  --color-danger: #dc3545;
  --color-warning: #ffc107;
  --color-info: #0dcaf0;

  /* Couleurs de fond */
  --bg-primary: #ffffff;
  --bg-secondary: #f8f9fa;
  --bg-tertiary: #e9ecef;

  /* Couleurs de texte */
  --text-primary: #212529;
  --text-secondary: #6c757d;
  --text-tertiary: #adb5bd;

  /* Couleurs de bordure */
  --border-color: #dee2e6;
  --border-color-subtle: #e9ecef;

  /* Couleurs d&#39;ombre */
  --shadow-sm: rgba(0, 0, 0, 0.075);
  --shadow-md: rgba(0, 0, 0, 0.15);
  --shadow-lg: rgba(0, 0, 0, 0.25&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_معرفی&quot;&gt;معرفی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مشکل_وابستگی_به_gradlerunner&quot;&gt;مشکل: وابستگی به GradleRunner&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_پیشزمینه_توسعه_پلاگین&quot;&gt;پیش‌زمینه توسعه پلاگین&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_دایلم_لاگینگ&quot;&gt;دایلم لاگینگ&lt;/a&gt;&lt;/li&gt;
