&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استخراج_اطلاعات_از_خروجی&quot;&gt;استخراج اطلاعات از خروجی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// Recherche simple
val hasMessage = result.output.contains(&quot;Expected message&quot;)

// Extraction avec regex
val versionRegex = Regex(&quot;Version: (.+)&quot;)
val version = versionRegex.find(result.output)?.groupValues?.get(1)

// Filtrage de lignes
val errorLines = result.output.lines()
    .filter { it.contains(&quot;ERROR&quot;) }

errorLines.forEach { logger.error(&quot;Gradle error: $it&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقایسه_قبلبعد&quot;&gt;مقایسه قبل/بعد&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_قبل_رویکرد_مشکلمحور&quot;&gt;قبل : رویکرد مشکل‌محور&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class MyTest {
    lateinit var logger: Logger // ❌ Initialisé tardivement

    @BeforeEach
    fun setup() {
        logger = LoggerFactory.getLogger(...) // ❌ Dépendance
    }

    @Test
    fun test() {
        val runner = GradleRunner.create()
        logger.info(&quot;Testing...&quot;) // ⚠ Peut échouer
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پس_رویکرد_مقاوم&quot;&gt;پس : رویکرد مقاوم&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class MyTest {
    companion object {
        private val logger = LoggerFactory.getLogger(...) // ✓ Indépendant
    }

    @Test
    fun test() {
        logger.info(&quot;TEST: Starting...&quot;) // ✓ Toujours disponible

        val result = GradleRunner.create()
            .forwardOutput() // ✓ Capture la sortie
            .build()

        logger.debug(&quot;Output: ${result.output}&quot;) // ✓ Analyse
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دیاگرام_خلاصه&quot;&gt;دیاگرام خلاصه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
skinparam backgroundColor #FEFEFE

title جریان کامل لاگ در تست‌های عملکردی
actor &quot;توسعه‌دهنده&quot; as dev
participant &quot;JUnit&quot; as junit
participant &quot;TestClass&quot; as test
participant &quot;لاگر
(SLF4J)&quot; as logger
participant &quot;Logback&quot; as logback
participant &quot;GradleRunner&quot; as runner
participant &quot;کنسل/فایل&quot; as output

dev -&amp;gt; junit : lance les tests

activate junit
junit -&amp;gt; test : charge la classe
activate test

test -&amp;gt; logger : initialize (companion)
activate logger
logger -&amp;gt; logback : configure
activate logback
logback --&amp;gt; logger : ready
deactivate logback
logger --&amp;gt; test : ✓
deactivate logger

== Phase de Setup ==

junit -&amp;gt; test : @BeforeAll
test -&amp;gt; logger : info(&quot;راه‌اندازی&quot;)
logger -&amp;gt; output : [INFO] Initialisation

junit -&amp;gt; test : @BeforeEach
test -&amp;gt; logger : debug(&quot;تست تنظیم&quot;)
logger -&amp;gt; output : [DEBUG] Setup test

== Phase de Test ==

junit -&amp;gt; test : @Test
test -&amp;gt; logger : info(&quot;TEST: شروع&quot;)
logger -&amp;gt; output : [INFO] TEST: Starting

test -&amp;gt; runner : create()
activate runner

test -&amp;gt; runner : .forwardOutput()
test -&amp;gt; runner : .build()

runner -&amp;gt; runner : execute Gradle
runner --&amp;gt; test : BuildResult + output text
deactivate runner

test -&amp;gt; logger : debug(&quot;تحلیل خروجی&quot;)
logger -&amp;gt; output : [DEBUG] Analyzing output

test -&amp;gt; test : assertions
test -&amp;gt; logger : info(&quot;✓ تست موفق&quot;)
logger -&amp;gt; output : [INFO] ✓ Test passed

== Phase de Cleanup ==

junit -&amp;gt; test : @AfterEach
test -&amp;gt; logger : debug(&quot;پاک‌سازی&quot;)
logger -&amp;gt; output : [DEBUG] Cleanup

junit -&amp;gt; test : @AfterAll
test -&amp;gt; logger : info(&quot;پایان تست‌ها&quot;)
logger -&amp;gt; output : [INFO] Fin des tests

test --&amp;gt; junit : ✓ all tests passed
deactivate test
deactivate junit

dev &amp;lt;-- junit : rapport de tests

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اجتناب_از_دامها&quot;&gt;اجتناب از دام‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پنچهٔ_شماره_یک_فراموش_کردن_forwardoutput&quot;&gt;❌ پنچهٔ شماره یک : فراموش کردن `.forwardOutput()&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS: La sortie Gradle n&#39;est pas capturée
val result = GradleRunner.create()
    .withArguments(&quot;task&quot;)
    .build()

// result.output sera vide !&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON: La sortie est capturée
val result = GradleRunner.create()
    .forwardOutput() // ✓
    .withArguments(&quot;task&quot;)
    .build()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فخ_۲_لاگِر_راهاندازی_نشده&quot;&gt;❌ فخ ۲ : لاگِر راه‌اندازی نشده&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS
class Test {
    lateinit var logger: Logger // Peut ne pas être initialisé
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON
class Test {
    companion object {
        private val logger = LoggerFactory.getLogger(...) // Toujours initialisé
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فخ_شماره_۳_لاگینگ_مفرط&quot;&gt;❌ فخ شماره ۳ : لاگینگ مفرط&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS: Trop de logs DEBUG en production
logger.debug(&quot;Variable a = $a&quot;)
logger.debug(&quot;Variable b = $b&quot;)
logger.debug(&quot;Variable c = $c&quot;)
// ... 100 lignes de logs&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON: Logging ciblé
logger.info(&quot;Traitement de ${items.size} éléments&quot;)
logger.debug(&quot;Détails: ${items.take(5)}...&quot;) // Échantillon seulement&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتایج_و_معیارها&quot;&gt;نتایج و معیارها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;با این روش، شما دریافت می‌کنید:&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 28.5714%;&quot;&gt;
&lt;col style=&quot;width: 42.8571%;&quot;&gt;
&lt;col style=&quot;width: 28.5715%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;متریک&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;قبل&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;پس&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;خطوط کد&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;تقریباً ۵۰ خط&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~80 خطوط (+60%)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;زمان دیباگ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;تقریباً ۳۰ دقیقه&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~5 دقیقه (-83%)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;خطاهای شناسایی شده&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;أساسي&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;دقیق&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;نگهداری&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;سخت&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ساده&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;استقلال&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پیوسته&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مستقل&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجه&quot;&gt;نتیجه&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;قرار دادن یک سیستم لاگینگ مقاوم در تست‌های عملکردی پلاگین‌های Gradle بر پایهٔ یک اصل ساده است :&lt;strong&gt;استقلال&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نکات کلیدی که باید به خاطر سپرد:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لاگر مستقل&lt;/strong&gt;: در یک`companion object`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SLF4J و Logback&lt;/strong&gt;: استاک آزمایش‌شده و قابل تنظیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;.forwardOutput()&lt;/strong&gt;گرفتن خروجی Gradle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لاگ منظم&lt;/strong&gt;: INFO برای مراحل، DEBUG برای جزئیات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تحلیل خروجی&lt;/strong&gt;: استخراج اطلاعات از`result.output`&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;این روش تست‌ها را تضمین می‌کند.&lt;strong&gt;قابل نگهداری&lt;/strong&gt;, &lt;strong&gt;قابل رفع اشکال&lt;/strong&gt; et &lt;strong&gt;مستحکم&lt;/strong&gt;, در حالی که به اصول طراحی پایدار پایبند است.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_منابع&quot;&gt;منابع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/test_kit.html&quot;&gt;مستندات Gradle TestKit&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://www.slf4j.org/manual.html&quot;&gt;راهنمای SLF4J&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://logback.qos.ch/manual/configuration.html&quot;&gt;Logback پیکربندی&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/gradle/gradle/tree/master/subprojects/test-kit&quot;&gt;کد منبع Gradle TestKit&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دورتر_برو&quot;&gt;دورتر برو&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;در یک مقاله‌ی آتی، ما مورد بررسی قرار خواهیم داد :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;یکپارچه‌سازی متمرکز با لاگ‌گیری ساختار یافته&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;گزارش‌های HTML تست‌ها با لاگ‌های ادغام‌شده&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دیبگ پیشرفته با پیوستن JVM&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;عمل بهینه‌سازی و عملکرد لاگینگ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;این مقاله بخشی از سری «توسعه پلاگین Gradle» در وبلاگ تکنیکی من است.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

