&lt;li&gt;&lt;a href=&quot;#_بهبود_دسترسیپذیری&quot;&gt;بهبود دسترسی‌پذیری&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مثال_واقعی_مستندات_تمها&quot;&gt;مثال واقعی: مستندات تم‌ها&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجه&quot;&gt;نتیجه&lt;/a&gt;&lt;/li&gt;
