&lt;h2 id=&quot;start&quot;&gt;متغیرها، عملگرهای حسابی و رشته‌های کاراکتری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;01_start.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Variables
 */
//une variable stupide
var my_variable = &quot;dummy variable&quot;;
console.log(my_variable);

//assertion
console.assert(my_variable === &quot;dummy variable&quot;);

var username = &quot;cheroliv&quot;;
console.log(username);
console.assert(username === &quot;cheroliv&quot;);

//concaténation de string
console.assert(username === &quot;cher&quot; + &quot;oliv&quot;);

/**
 *  Opérateur arithmétique: + - * / %
 */
//integer
var x = 10;
var y = 5;
var z = 20;

console.log(x + y);
console.assert(x + y === 15);

console.log(x + y - z);
console.assert(x + y - z === -5);


console.log(x - y);
console.assert(x - y === 5);


console.log(x * y);
console.assert(x * y === 50);

console.log(x / y);
console.assert(x / y === 2);


console.log(&quot;---------&quot;);

x = 20;
y = 10;

console.log(x + y);
console.assert(x + y === 30);

console.log(x + y - z);
console.assert(x + y - z === 10);


console.log(x - y);
console.assert(x - y === 10);

console.log(x * y);
console.assert(x * y === 200);

console.log(x / z);
console.assert(x / z === 1);


//Littéraux de gabarits pour string avec backstick `
//Template literals (Template strings)
console.assert(`typeof z: ${typeof z}` === &quot;typeof z: number&quot;);

console.log(`x is type of : ${typeof x}`);
console.log(`y is type of : ${typeof y}`);
console.log(`z is type of : ${typeof z}`);

//typeof: donne le type de la variable
console.assert(typeof x === &quot;number&quot;);
console.assert(typeof y === &quot;number&quot;);
console.assert(typeof z === &quot;number&quot;);


console.log(&quot;---------&quot;);
/**
 * Incrémenation/décrémentation
 */
//incrémantation/décrémentation préfixe
console.log(++x) //incrémenté puis affiché: 21
console.log(x) //la valeur incrémenté: 21

//incrémantation/décrémentation suffixe
console.log(y++) //affiche la valeur sans incrémenation puis incrémente: 10
console.log(y) //la valeur incrémenté: 11

//décrémentation
x--;
y--;
console.assert(x === 20);
console.assert(y === 10);


/**
 * String: chaine de caractères
 */
console.log(`username: ${username}`);

//taille de la string
console.log(`username.length: ${username.length}`);
console.assert(username.length === 8);
console.assert(username.length === &quot;cheroliv&quot;.length);
console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;arrays&quot;&gt;آرایه‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;02_arrays.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Les arrays
 */
// auteurs [[&quot;nom &quot;, &quot;prénom&quot;, &quot;pays&quot;]]
var writers = [
    [&quot;Karl&quot;, &quot;Marx&quot;, &quot;de&quot;],
    [&quot;Jean-Jacques&quot;, &quot;Rousseau&quot;, &quot;fr&quot;],
    [&quot;Victor&quot;, &quot;Hugo&quot;, &quot;fr&quot;],
    [&quot;René&quot;, &quot;Descartes&quot;, &quot;fr&quot;],
    [&quot;Paul&quot;, &quot;Verlaine&quot;, &quot;fr&quot;],
    [&quot;Antonio&quot;, &quot;Gramsci&quot;, &quot;it&quot;],
    [&quot;Georg&quot;, &quot;Lukacs&quot;, &quot;hu&quot;],
    [&quot;Franz&quot;, &quot;Kafka&quot;, &quot;hu&quot;],
    [&quot;Arthur&quot;, &quot;Rimbaud&quot;, &quot;fr&quot;],
    [&quot;Gérard&quot;, &quot;de Nerval&quot;, &quot;fr&quot;],
    [&quot;Chrétien&quot;, &quot;de Troyes&quot;, &quot;fr&quot;],
    [&quot;François&quot;, &quot;Rabelais&quot;, &quot;fr&quot;],
    [&quot;Georg&quot;, &quot;Hegel&quot;, &quot;de&quot;],
    [&quot;Friedrich&quot;, &quot;Engels&quot;, &quot;de&quot;],
]

console.table(writers);

// accés aux élèments du tableau
console.log(writers[0]);
console.log(`${writers[0][0]}, ${writers[0][1]} (${writers[0][2]})`);
console.assert(&quot;Karl, Marx (de)&quot; === `${writers[0][0]}, ${writers[0][1]} (${writers[0][2]})`);

//sauvegarder la valeur du prénom de Marx
var karl = writers[0][0]

//éditer un élement du tableau, le prénom de Marx
writers[0][0] = &quot;Karlito&quot;

console.log(`${writers[0][0]}, ${writers[0][1]} (${writers[0][2]})`);
console.assert(&quot;Karlito, Marx (de)&quot; === `${writers[0][0]}, ${writers[0][1]} (${writers[0][2]})`);

console.assert(&quot;Karl&quot; === karl);

//remettre la valeur initale du prénom de Marx
writers[0][0] = karl;

console.assert(`${karl}, Marx (de)` === `${writers[0][0]}, ${writers[0][1]} (${writers[0][2]})`);

console.log(&quot;---------&quot;);

/**
 *  Arrays: map/forEach/pop/push/slice/sort/shift/unshift
 */

var numbers = [1, 5, 4, 3, 2];

console.log(&quot;Iterate with forEach&quot;);
// parcourir avec array.forEach
numbers.forEach((it) =&amp;gt; console.log(it));
console.log(&quot;---------&quot;);

console.log(&quot;Iterate with map&quot;);
// parcourir avec array.map
numbers.map((it) =&amp;gt; console.log(it));
console.log(&quot;---------&quot;);

//afficher les éléments sur une ligne
//génère la string avec le formatage des nombres
const numbersString = (numberArray) =&amp;gt; {
    var consoleOutput = new String();
    numberArray.forEach(number =&amp;gt; consoleOutput += `${number}, `);
    return consoleOutput = consoleOutput.substring(0, consoleOutput.length - 2);
};

//affiche la chaine entre crochets dans la console
const displayNumbers = (numbersStr) =&amp;gt; {
    console.log(`[${numbersString(numbersStr)}]`);
};

console.log(&quot;orginal number array&quot;)
displayNumbers(numbers);
console.log(&quot;---------&quot;);


//push: ajoute à la fin
console.log(&quot;push&quot;);
numbers.push(6);
displayNumbers(numbers);
console.log(&quot;---------&quot;);

//pop: suprime le dernier
console.log(&quot;pop&quot;);
numbers.pop();
displayNumbers(numbers);
console.log(&quot;---------&quot;);

//unshift: ajouter le parametre au debut de l&#39;array
console.log(&quot;unshift&quot;);
numbers.unshift(0);
displayNumbers(numbers);
console.log(&quot;---------&quot;);

//shift: supprime le premier element de l&#39;array
console.log(&quot;shift&quot;);
numbers.shift();
displayNumbers(numbers);
console.log(&quot;---------&quot;);

//slice: renvoi l&#39;array entre les positions en argument
console.log(&quot;slice&quot;);
var sliceNumbersResult = numbers.slice(2, 4);
displayNumbers(sliceNumbersResult);
console.log(&quot;---------&quot;);

//sort asc
console.log(&quot;sort asc&quot;);
var ascSort = numbers.sort((a, b) =&amp;gt; a - b);
displayNumbers(ascSort);
console.log(&quot;---------&quot;);

//sort desc
console.log(&quot;sort desc&quot;);
var descSort = numbers.sort((a, b) =&amp;gt; b - a);
displayNumbers(descSort);
console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;functions&quot;&gt;توابع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;03_functions.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 *  Les fonctions
 */

//function style legacy
function sayHelloWorldLegacy() {
    console.log(&quot;Hello world legacy!&quot;);
}
sayHelloWorldLegacy();

function sayHelloLegacy(firstName, lastName, style) {
    console.log(`Hello ${firstName}, ${lastName} (${style})`);
}
sayHelloLegacy(&quot;Cher&quot;, &quot;Oliv&quot;, &quot;legacy&quot;);

console.log(&quot;---------&quot;);

//function style arrow
const sayHelloWorld = () =&amp;gt; console.log(&quot;Hello world!&quot;);
sayHelloWorld();

const sayHello = (firstName, lastName) =&amp;gt;
    console.log(`Hello ${firstName}, ${lastName}`);
sayHello(&quot;Cher&quot;, &quot;Oliv&quot;);

console.log(&quot;---------&quot;);

var authors = [
    [&quot;Chrétien&quot;, &quot;de Troyes&quot;, &quot;fr&quot;],
    [&quot;François&quot;, &quot;Rabelais&quot;, &quot;fr&quot;],
    [&quot;René&quot;, &quot;Descartes&quot;, &quot;fr&quot;],
    [&quot;Jean-Jacques&quot;, &quot;Rousseau&quot;, &quot;fr&quot;],
    [&quot;Georg&quot;, &quot;Hegel&quot;, &quot;de&quot;],
    [&quot;Karl&quot;, &quot;Marx&quot;, &quot;de&quot;],
    [&quot;Friedrich&quot;, &quot;Engels&quot;, &quot;de&quot;],
    [&quot;Victor&quot;, &quot;Hugo&quot;, &quot;fr&quot;],
    [&quot;Paul&quot;, &quot;Verlaine&quot;, &quot;fr&quot;],
    [&quot;Antonio&quot;, &quot;Gramsci&quot;, &quot;it&quot;],
    [&quot;Georg&quot;, &quot;Lukacs&quot;, &quot;hu&quot;],
    [&quot;Franz&quot;, &quot;Kafka&quot;, &quot;hu&quot;],
    [&quot;Arthur&quot;, &quot;Rimbaud&quot;, &quot;fr&quot;],
    [&quot;Gérard&quot;, &quot;de Nerval&quot;, &quot;fr&quot;],
]


const displayAuthors = (authorsArray) =&amp;gt; authorsArray.forEach(author =&amp;gt;
    console.log(`${author[0]} ${author[1]}, (${author[2]})`)
);

displayAuthors(authors);

console.log(&quot;---------&quot;);

/**
 * valeur par défaut des parametres d&#39;une fonctions
 */
const add = (a = 0, b = 0) =&amp;gt; a + b;
console.assert(add() === 0)
console.assert(add(1) === 1)
console.assert(add(1, 1) === 2)

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;param_x_scope&quot;&gt;پارامترها و دامنه‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;04_param_x_scope.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;//global scope: visible partout, dans et hors functions
var global;

const foo = () =&amp;gt; {
    //local scope: visible uniquement dans la fonction foo
    var bar = &quot;bar&quot;
    console.log(bar)
}

foo();
console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;objects&quot;&gt;اشیاء&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;05_objects.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Les objects
 */
var authors = [
    [&quot;Chrétien&quot;, &quot;de Troyes&quot;, &quot;fr&quot;],
    [&quot;François&quot;, &quot;Rabelais&quot;, &quot;fr&quot;],
    [&quot;René&quot;, &quot;Descartes&quot;, &quot;fr&quot;],
    [&quot;Jean-Jacques&quot;, &quot;Rousseau&quot;, &quot;fr&quot;],
    [&quot;Georg&quot;, &quot;Hegel&quot;, &quot;de&quot;],
    [&quot;Karl&quot;, &quot;Marx&quot;, &quot;de&quot;],
    [&quot;Friedrich&quot;, &quot;Engels&quot;, &quot;de&quot;],
    [&quot;Victor&quot;, &quot;Hugo&quot;, &quot;fr&quot;],
    [&quot;Paul&quot;, &quot;Verlaine&quot;, &quot;fr&quot;],
    [&quot;Antonio&quot;, &quot;Gramsci&quot;, &quot;it&quot;],
    [&quot;Georg&quot;, &quot;Lukacs&quot;, &quot;hu&quot;],
    [&quot;Franz&quot;, &quot;Kafka&quot;, &quot;hu&quot;],
    [&quot;Arthur&quot;, &quot;Rimbaud&quot;, &quot;fr&quot;],
    [&quot;Gérard&quot;, &quot;de Nerval&quot;, &quot;fr&quot;],
];

var hugo = {
    firstName: authors[7][0],
    lastName: authors[7][1],
    country: authors[7][2],
};

var book = {
    author: hugo,
    title: &quot;Les misérables&quot;
};
console.log(hugo);
console.log(book);

//accéder à un membre de l&#39;objet par point
console.log(hugo.country);

//accéder à un membre de l&#39;objet par crochet
console.log(book[&quot;title&quot;]);

console.log(book.author.lastName);

console.log(book[&quot;author&quot;][&quot;firstName&quot;]);

//ajouter une clé a un objet
hugo.gender = &quot;non binary&quot;;
console.assert(hugo.gender === &quot;non binary&quot;);


//mettre à jour une clé
hugo.gender = &quot;male&quot;;
console.assert(hugo.gender !== &quot;non binary&quot;);
console.assert(hugo[&quot;gender&quot;] === &quot;male&quot;);

//supprimer une clé
delete hugo.gender;


//verfier que l&#39;objet ne contient pas la clé gender
console.assert(!Object.keys(hugo).includes(&quot;gender&quot;));


console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;loops&quot;&gt;حلقه‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;06_loops.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Les boucles: Itérer sur arrays et objets.
 */

console.log(&quot;for loop over array&quot;);

var numbers = [12, 10, 8, 6, 4, 2, 0];

for (number of numbers) {
    console.log(number);
}

console.log(&quot;---------&quot;);

console.log(&quot;for loop over object key&quot;);

var obj = { a: 1, b: 2, c: 3, d: 4 };

for (key in obj) {
    console.log(key);
}

console.log(&quot;---------&quot;);

console.log(&quot;for loop over object value&quot;);

for (value in obj) {
    console.log(obj[value]);
}

console.log(&quot;---------&quot;);

console.log(&quot;another for loop over authors array&quot;)

var authors = [
    [&quot;Chrétien&quot;, &quot;de Troyes&quot;, &quot;fr&quot;],
    [&quot;François&quot;, &quot;Rabelais&quot;, &quot;fr&quot;],
    [&quot;René&quot;, &quot;Descartes&quot;, &quot;fr&quot;],
    [&quot;Jean-Jacques&quot;, &quot;Rousseau&quot;, &quot;fr&quot;],
    [&quot;Georg&quot;, &quot;Hegel&quot;, &quot;de&quot;],
    [&quot;Karl&quot;, &quot;Marx&quot;, &quot;de&quot;],
    [&quot;Friedrich&quot;, &quot;Engels&quot;, &quot;de&quot;],
    [&quot;Victor&quot;, &quot;Hugo&quot;, &quot;fr&quot;],
    [&quot;Paul&quot;, &quot;Verlaine&quot;, &quot;fr&quot;],
    [&quot;Antonio&quot;, &quot;Gramsci&quot;, &quot;it&quot;],
    [&quot;Georg&quot;, &quot;Lukacs&quot;, &quot;hu&quot;],
    [&quot;Franz&quot;, &quot;Kafka&quot;, &quot;hu&quot;],
    [&quot;Arthur&quot;, &quot;Rimbaud&quot;, &quot;fr&quot;],
    [&quot;Gérard&quot;, &quot;de Nerval&quot;, &quot;fr&quot;],
];

for (const [i, value] of authors.entries()) {
    console.log(`${value[0]}, ${value[1]} (${value[2]})`);
}

console.log(&quot;---------&quot;);

console.log(&quot;while loop over array&quot;)

var i = 0
while (i &amp;lt; authors.length) {
    console.log(`${authors[i][0]}, ${authors[i][1]} (${authors[i][2]})`);
    i++;
}

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;const_var_let&quot;&gt;const, var و let&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;07_const_var_let.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * const X var X let
 */
//var x du if n&#39;est pas confiné au scope du if
const varTest = () =&amp;gt; {
    var x = 1;
    console.log(x);
    console.assert(x === 1);
    if (true) {
        var x = 2;
        console.log(x);
        console.assert(x === 2);
    }
    console.log(x);
    console.assert(x !== 1);
    console.assert(x === 2);
}
varTest();

console.log(&quot;---------&quot;);

//var x est global à tous les fichier js
//chargés dans la page html
//var x issue du fichier 1_start.js
//ligne 46
console.log(x);
console.assert(x === 20);

console.log(&quot;---------&quot;);

//premier let x est confiné au scope de la fonction
//le let x du if est confiné au scope du if
const letTest = () =&amp;gt; {
    let x = 1;
    console.log(x);
    console.assert(x === 1);
    if (true) {
        let x = 2;
        console.log(x);
        console.assert(x === 2);
    }
    console.log(x);
    console.assert(x === 1);
    console.assert(x !== 2);
}
letTest();

console.log(&quot;---------&quot;);

/**
 * const: déclare un emplacement mémoire non réattribuable
 * c&#39;est modifiable pour un array,
 * mais non réinitialisable;
 * ex:
 * const arr = [25, 27, 29]
 * arr = [5, 7] //impossible
 * arr[0]=20 // possible
 * ex:
 * const n = 1;
 * n = 3; //impossible
 */
const arr = [25, 27, 29]
console.table(arr);
arr[0] = 20 // possible
console.table(arr);

arr.pop()
console.table(arr);
console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;rest_and_spread_operators&quot;&gt;Rest و spread operators&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;08_عملگرهای_rest_و_spread.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérateur de rest:
 * const add = (...operandes) =&amp;gt; a + b;
 * ou avec parametres avec valeur par défaut
 * const add = (a=0, b=0, ...operandes) =&amp;gt; a + b;
 */

/**
 * spread opérateur:
 * récupère l&#39;ensemble des elements d&#39;une collection,
 * dans un array
 */
const user_ages = [25, 56, 12, 58, 41, 62, 26];

const max_user_age = Math.max(...user_ages);
const min_user_age = Math.min(...user_ages);

console.assert(max_user_age == 62);
console.assert(min_user_age == 12);

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;destructuring&quot;&gt;تخریب‌سازی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;09_destructuring.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * L&#39;affectation par décomposition (destructuring)
 */

const user = {
    first_name: &quot;Oliv&quot;,
    last_name: &quot;Cher&quot;,
    nick_name: &quot;cheroliv&quot;,
    gender: &quot;male&quot;,
    is_adult: true
};
console.log(user);

//première façon d&#39;initaliser des variables sans destructuration
let first_name_legacy = user.first_name;
let last_name_legacy = user.last_name;
let nick_name_legacy = user.nick_name;
let gender_legacy = user.gender;
let is_adult_legacy = user.is_adult;

console.assert(&quot;Oliv&quot; === first_name_legacy);
console.assert(&quot;Cher&quot; === last_name_legacy);
console.assert(&quot;cheroliv&quot; === nick_name_legacy);
console.assert(&quot;male&quot; === gender_legacy);
console.assert(true === is_adult_legacy);
console.log(&quot;---------&quot;);
/**
 * Initialisation par déstructuration
 */
const {
    first_name,
    last_name,
    nick_name,
    gender,
    is_adult
} = user;

console.assert(user.first_name === first_name);
console.assert(user.last_name === last_name);
console.assert(user.nick_name === nick_name);
console.assert(user.gender === gender);
console.assert(user.is_adult === is_adult);

/**
 * Intialisation par déstructuration des arrays
 */
//cible explicite
const [a1, a2] = [15, 25, 17, 81, 51, 46];
console.assert(a1 === 15);
console.assert(a2 === 25);

//cible avec position par rapport aux index par virgules
//je veux b3 à 46
const [b1, b2, , , , b3] = [15, 25, 17, 81, 51, 46];
console.assert(b1 === 15);
console.assert(b2 === 25);
console.assert(b3 === 46);

//déstructuration avec operateur de rest
// je contruit un autre avec avec les elements
// à partir du premier élèment non destructuré
const [c1, c2, ...sub_arr] = [15, 25, 17, 81, 51, 46];
console.assert(b1 === 15);
console.assert(b2 === 25);
console.assert(sub_arr.length === 4);
console.assert(sub_arr[0] === 17);
console.assert(sub_arr[1] === 81);
console.assert(sub_arr[2] === 51);
console.assert(sub_arr[3] === 46);


// Une boucle pour comparer le resultat attendu
for (const [i, value] of[15, 25, 17, 81, 51, 46].entries()) {
    //on reconstruit le tableau à chaque iteration
    console.assert([c1, c2].concat(sub_arr)[i] === value);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;import_export&quot;&gt;واردات و صادرات ماژول‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;10_module_import_export.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Import et export de module
 *
 * Dans le fichier html
 * au niveau de la balise d&#39;import de script
 * spécifier le type module
 *
 * 1er technique: import nommé des fonctions:
 * import { sum, minus, times, div, rem } from &quot;./dummy_math_functions.js&quot;;
 *
 * 2eme technique: import global des fonction avec l&#39;asterisque(*)
 * en préfixant l&#39;import par un nommage du fichier importé:
 * import * as math from &quot;./dummy_math_functions.js&quot;;
 *
 * 3eme technique: import par alias avec le mot clé &quot;as&quot;
 * import {
 *     sum as add,
 *     minus as substract,
 *     times as multiply,
 *     div as divide,
 *     rem as modulo
 * } from &quot;./dummy_math_functions.js&quot;;
 */

import {
    sum,
    minus,
    times,
    div,
    rem
} from &quot;./dummy_math_functions.js&quot;;

console.assert(sum(1, 1) === 2);
console.assert(minus(4, 2) === 2);
console.assert(times(2, 2) === 4);
console.assert(div(4, 2) === 2);
console.assert(rem(4, 2) === 0);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فرضی_ریاضی_توابع.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;//sum
const sum = (x, y) =&amp;gt; x + y;

// subtraction
const minus = (x, y) =&amp;gt; x - y;

// multiplication
const times = (x, y) =&amp;gt; x * y;

// division
const div = (x, y) =&amp;gt; x / y;

// remainder: reste de la division euclidiene
const rem = (x, y) =&amp;gt; x % y;

// log sum
const sum_log = (x, y) =&amp;gt; console.log(sum(x, y));

// log subtraction
const minus_log = (x, y) =&amp;gt; console.log(minus(x, y));

// log multiplication
const times_log = (x, y) =&amp;gt; console.log(times(x, y));

// log division
const div_log = (x, y) =&amp;gt; console.log(div(x, y));

// log remainder
const rem_log = (x, y) =&amp;gt; console.log(rem(x, y));

export {
    sum,
    minus,
    times,
    div,
    rem,
    sum_log,
    minus_log,
    times_log,
    div_log,
    rem_log
};&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;classes&quot;&gt;استفاده از کلاس‌ها&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;11_classes.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Utilisation des classes
 */
//creation d&#39;un objet
class Account {
    constructor(username) {
        this.username = username;
    }
};

const acc1 = new Account(&quot;cheroliv&quot;);
console.table(acc1);
console.assert(acc1.username === &quot;cheroliv&quot;);

console.log(&quot;---------&quot;);

//création d&#39;un objet et ajout de getter et setter(accesseurs)
class AccountInfo {
    constructor(username) {
        this._username = username;
    }

    get username() {
        return this._username;
    }

    /**
     * @param {(arg0: string) =&amp;gt; void} new_username
     */
    set new_username(new_username) {
        this._username = new_username;
    }
};

const acc_info1 = new AccountInfo(&quot;cheroliv&quot;);
console.table(acc_info1);
//accés au membre _username avec le getter username()
console.assert(acc_info1.username === &quot;cheroliv&quot;);

//update la valeur username de acc_info1 avec le setter
acc_info1.new_username = &quot;imrandeh&quot;;
console.assert(acc_info1.username === &quot;imrandeh&quot;);

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro Javascript&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_قالببندی&quot;&gt;قالب‌بندی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_1_بینش&quot;&gt;کارگاه 1: بینش&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_1_الگو_qqoqcp_چه_کسی_چه_چیزی_کجا_چه_زمانی_چگونه_چرا&quot;&gt;1. الگو «QQOQCP» – چه کسی, چه چیزی, کجا, چه زمانی, چگونه, چرا&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_۲_بورد_وِژن_محصول&quot;&gt;۲. بورد وِژن محصول&lt;/h4&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_گروه_هدف&quot;&gt;گروه هدف&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کدامان کاربران هستند که محصول یا پیش‌انهد را استفاده می‌کنند؟ (مستقیم، غیرمستقیم)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_نیازها&quot;&gt;نیازها&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نیازهای اصلی ۵ کاربران کلیدی برنامه چه هستند؟&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_محصول&quot;&gt;محصول&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پیشنهاد ارزش من چیست؟ ویژگی‌های اصلی 5 محصول چه هستند که به &amp;#8230;&amp;#8203; اجازه می‌دهند پاسخ دهند؟ نیازها&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_هدف_کسبوکار&quot;&gt;هدف کسب‌وکار&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معیارهای موفقیت چه هستند؟&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_بینش&quot;&gt;بینش&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;هنگامی که ۴ ستون کامل شد، لازم است بخش visions محصول Product Vision را پر بورد در یک جمله کامل.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_2_شخصاهامسیرهای_کاربران&quot;&gt;کارگاه 2: شخصاها/مسیرهای کاربران&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;برای هر persona یک مسیر کاربری تعریف کنید:&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;کی می‌خواهد از خدمات من استفاده کند؟ (هدف)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او می‌خواهد چه کاری انجام دهد؟ (اما)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;او چگونه آن را انجام خواهد داد؟ (مسیر کاربری)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_3_زونینگ_استوری_بورد_نقشه_سایت&quot;&gt;کارگاه 3: زونینگ، استوری بورد، نقشه سایت&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_1_تقسیمبندی&quot;&gt;1. تقسیم‌بندی&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_2_استوریبورد&quot;&gt;2. استوریبورد&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_3_نقشه_سایت&quot;&gt;3. نقشه سایت&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_۴_چارچوب_سیمداربورد_احساس&quot;&gt;کارگاه ۴: چارچوب سیم‌دار/بورد احساس&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_۱_wireframes&quot;&gt;۱. Wireframes&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_2_مودبورد&quot;&gt;2. مودبورد&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_5_نقشهسازی_داستان_داستانهای_کاربر&quot;&gt;کارگاه 5: نقشه‌سازی داستان/ داستان‌های کاربر&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_story_mapping_اولویتبندی_قصههای_کاربری&quot;&gt;Story mapping (اولویت‌بندی قصه‌های کاربری)&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_به_عنوان_type_dutilisateur_من_میخواهم_un_objectif_تا_une_raison&quot;&gt;به عنوان &amp;lt;type d&amp;#8217;utilisateur&amp;gt;, من می‌خواهم &amp;lt;un objectif&amp;gt; تا &amp;lt;une raison&amp;gt;.&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_۶_backlog&quot;&gt;کارگاه ۶: Backlog&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://www.atlassian.com/fr/agile/scrum/backlogs&quot;&gt;کارهای معطلی&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاه_7_تکنیک_و_معماری&quot;&gt;کارگاه 7: تکنیک و معماری&lt;/h3&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_لینکهای_خوب&quot;&gt;لینک‌های خوب&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://play.kotlinlang.org/&quot;&gt;kotlinlang playground&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arrow-kt.io/&quot;&gt;arrow.kt&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arkivanov.github.io/MVIKotlin/&quot;&gt;MVI:مدل نمایش نیّت&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/arkivanov/Essenty&quot;&gt;ضروری&lt;/a&gt;&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arkivanov.github.io/Decompose/&quot;&gt;تجزیه کن&lt;/a&gt;&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_قطعه_کد_متنوع&quot;&gt;قطعه کد متنوع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نقش_و_کاهش&quot;&gt;نقش و کاهش&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تبدیل یک لیست bite به یک لیست string و خلاصه‌سازی لیست string&lt;br&gt;
در یک رشته‌ای شامل concatenation چگونه لاگ کنیم درخواست ارسال شده(requestBodyContent:byte[])&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;log.info(
    requestBodyContent!!.map { it.toInt().toChar().toString() }
        .reduce { request: String, s: String -&amp;gt; request + s }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_enum_و_کلاسهای_بسته&quot;&gt;enum و کلاس‌های بسته&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پست:&lt;a href=&quot;0038_training_kotlin_enum_sealed_class_post&quot; target=&quot;&quot;_blank&quot;&gt;آموزش kotlin enum sealed class&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اینترفیس_عملکردی_و_ارجاع_متد&quot;&gt;اینترفیس عملکردی و ارجاع متد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;می‌توان یک موجودیت را به مدل دامنه DTO تبدیل کرد با یک متد ارجاع (سبک عملکردی - جاوا ۸)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;fun findAllByLoginNot(
        pageable:Pageable,
        login:String)
    :Page&amp;lt;UserDto&amp;gt; {
    return userDao.findAllByLoginNot(
                    pageable,
                    login).map(::fromEntity)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یکhttps://stackoverflow.com/a/22245383/837404[توضیح خوب]&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_خروجی_استاندارد_را_ضبط_کنید&quot;&gt;خروجی استاندارد را ضبط کنید&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.out
import java.lang.System.setOut
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals


class BasicsHOF {
    private val standardOut: PrintStream? = out
    private val outputStreamCaptor = ByteArrayOutputStream()

    @BeforeTest
    fun setUp() = setOut(PrintStream(outputStreamCaptor))

    @AfterTest
    fun tearDown() = setOut(standardOut)

    @Test
    fun `three times dope`() {

        3.times { println(&quot;Hello&quot;) }

        assertEquals(
            buildString {
                repeat(3) { append(&quot;Hello\n&quot;) }
                deleteAt(length - 1)
            }, outputStreamCaptor
                .toString()
                .trim()
        )
    }

    fun Int.times(fn: () -&amp;gt; Unit) = (1..this).forEach { _ -&amp;gt; fn() }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تفاوت_در_کاتلین_بین_apply_run_let_also_use_و_with_چیست&quot;&gt;تفاوت در کاتلین بین apply، run، let، also، use و with چیست؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مقایسه توابع Kotlin و استفاده از اشکال لامبدا مرجع&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_appliquer&quot;&gt;appliquer&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;مقدمه توابع Kotlin`apply`, &lt;code&gt;run&lt;/code&gt;, &lt;code&gt;let&lt;/code&gt;, &lt;code&gt;also&lt;/code&gt;, &lt;code&gt;use&lt;/code&gt;, et `with`طرز‌های مختلفی برای پردازش اشیاء ارائه می‌دهند. هر کدام موارد استفاده و رفتارهای خاص خود را دارند. علاوه بر این، اشکال lambda reference امکان می‌دهند تا کد را به وسیله ارجاع به توابع lambda موجود، بیشتر قابل خواندن و قابل استفاده دوباره کنند.&lt;/div&gt;
&lt;p&gt;تابع`apply`برای پیکربندی یک شیء در زمان ایجاد آن به کار می‌رود. شیءی که بر روی آن فراخوانی می‌شود را برمی‌گرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نمونه با ارجاع lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply(::configureObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply {
// configuration des propriétés de someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دوڑ&quot;&gt;دوڑ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وظیفهٔ`run`است برای اجرای یک بلوک کد بر روی یک شیء استفاده می‌شود و نتیجه‌ی آن بلوک کد را برمی‌گرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نمونه با ارجاع lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run(::someFunction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_let&quot;&gt;let&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تابع`let`استفاده می‌شود تا یک بلوک کد بر روی یک شیء اجرا شود و نتیجه‌ی آن بلوک کد را برگرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با ارجاع lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let(::processObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_همچنین&quot;&gt;همچنین = =&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وظیفه`also`برای انجام یک عمل اضافی بر روی یک شیء استفاده می‌شود و شیء‌ای که روی آن فراخوانی شده را برمی‌گرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با ارجاع لامبدا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also(::performAdditionalAction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also {
// action additionnelle sur someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استفاده&quot;&gt;استفاده&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عمل`use`برای کار با منابعی که باید بعد از استفاده بسته شوند، استفاده می‌شود. این به‌طور خودکار تابع را صدا می‌زند`close`در پایان بلوک.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با مرجع lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use(::useResource)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use {
// travailler avec la ressource
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_با&quot;&gt;با&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عملکرد`with`برای فراخوانی چندین متد بر روی یک объект بدون تکرار نام آن استفاده می‌شود و نتیجهٔ آخرین عبارت را برمی‌گرداند.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نمونه با ارجاع lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject, ::processWithObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال با lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject) {
// appeler des méthodes sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;با استفاده از اشکال lamdba reference یا بلوک‌ها`{}`, شما می‌توانید منطق را در توابع جداگانه بسته‌بندی کنید، به این ترتیب خوانایی و قابلیت استفاده مجدد کد را بهبود می‌بخشید.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_let_function_در_kotlin&quot;&gt;let Function در Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;آیا let شیء را با آثار جانبی اعمال‌شده بر روی آن یا در وضعیت اولیه ورودی، بسته به (let) برمی‌گرداند؟&lt;/div&gt;
&lt;p&gt;تابع`let`در Kotlin برای انجام عملیات بر روی یک شیء استفاده می‌شود و یک نتیجه مختلف بازگردانده می‌شود. اما باید توجه داشت که تابع`let`این، وضعیت اولیه شیء‌ای که بر روی آن فراخوانی می‌شود را تغییر نمی‌دهد.&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;امضا&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;inline fun &amp;lt;T, R&amp;gt; T.let(block: (T) &amp;#8594; R): R&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;استفاده&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;عمل`let`این به‌طور معمول برای اعمال تبدیل‌ها به یک شیء استفاده می‌شود و نتایجی حاصل می‌شود که بر پایهٔ این تبدیل‌ها است.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;نتیجه&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مقدار برگردانده شده توسط تابع`let`است نتیجه‌ی عبارت lambda که به‌عنوان آرگومان ارائه شده است، معمولاً نتیجه‌ی عملیاتی که بر روی شیء انجام می‌شود.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;اثرات لبه&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;هرچند که تابع`let`möglich است اثرات جانبی بر شیء داشته باشد وقتی در عبارت لامبدا استفاده می‌شود، اما وضعیت اولیه شیء خود را تغییر نمی‌دهد.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;به این ترتیب، تابع`let`این یک شیوه شایسته برای انجام عملیات روی یک شیء است، در حالی که یک نتیجه مشتق به دست می‌آید و در عین حال سلامت شیء اصلی حفظ می‌شود.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

